  ui_story_5014_50140201_27_dialog_content = "ใช่แล้ว ที่เราได้เจอกันก็เพราะความมุ่งมั่นและความปรารถนาในการสำรวจของเธอนะ",
  ui_story_5014_50140201_28_dialog_content = "จะว่าไป คนที่ส่งสัญญาณอาจจะตกลงมาติดอยู่ใต้ดินแบบเดียวกับเราก็ได้",
  ui_story_5014_50140201_29_dialog_content = "งั้นเราเดินเข้าไปสำรวจให้ลึกกว่านี้กันมั้ย? อาจจะได้เจอคนอื่นด้วย",
  ui_story_5014_50140201_30_dialog_content = "นั่นสิ ฉันก็คิดยังงั้นเหมือนกัน",
  ui_story_5014_50140201_31_dialog_content = "ยิ่งเจอคนมากเท่าไหร่ โอกาสรอดออกไปก็ยิ่งมากขึ้น",
  ui_story_5014_50140201_32_dialog_content = "มีพรรคพวกเยอะยังไงก็ดีกว่า",
  ui_story_5014_50140201_33_dialog_content = "ภูมิประเทศแถบนี้ส่วนใหญ่เป็นทุ่งหิมะบนภูเขา",
  ui_story_5014_50140201_34_dialog_content = "ถ้าเราโชคดี สุดปลายถ้ำอาจจะเป็นหุบเขาหรือทุ่งราบก็ได้",
  ui_story_5014_50140201_35_dialog_content = "แต่แผลของคาร์ลีน... เราพักกันอีกหน่อยดีกว่านะ",
  ui_story_5014_50140201_36_dialog_content = "ฉันบอกแล้วไงว่าไม่เป็นไร รีบไปกันเถอะ",
  ui_story_5014_50140201_37_dialog_content = "งั้นฉันจะช่วยเธอนะ ที่นี่มืดมาก ระวังตัวด้วยล่ะ",
  ui_story_5014_50140201_38_dialog_content = "ฉันจะใช้พลังจิตนำทางให้เอง",
  ui_story_5014_50140201_39_dialog_content = "<color=#e8d9bb>ซวบ ซวบ</color>",
  ui_story_5014_50140201_40_dialog_content = "ไวซ์ คาร์ลีน ดูนั่น!",
  ui_story_5014_50140201_41_dialog_content = "หลอดไฟเหรอ? แต่ดูเหมือนจะพังแล้วนะ...",
  ui_story_5014_50140201_42_dialog_content = "ไฟค้นหาของอิลลูมินา! มีคนอยู่ที่นี่จริง ๆ ด้วย!",
  ui_story_5014_50140201_43_dialog_content = "ไปกันต่อเถอะ",
  ui_story_5014_50140201_44_dialog_content = "<color=#e8d9bb>ซวบ ซวบ</color>",
  ui_story_5014_50140201_45_dialog_content = "แฮ่ก... แฮ่ก... เราเดินมานานแค่ไหนแล้วเนี่ย? ฉันจะไม่ไหวแล้ว...",
  ui_story_5014_50140201_46_dialog_content = "จะมีคนอยู่ในนี้จริงเหรอ? เราไม่เจอสัญญาณของคนเลยนะ นอกจากหลอดไฟพัง ๆ นั่น",
  ui_story_5014_50140201_47_dialog_content = "ฉันก็ไม่รู้เหมือนกัน... เรามาพักกันก่อนเถอะ",
  ui_story_5014_50140201_48_dialog_content = "เดี๋ยวนะ มีอากาศเคลื่อนไหว... มาจากข้างหน้าเรานี่แหละ!",
  ui_story_5014_50140201_49_dialog_content = "งั้นฉันไปดูให้!",
  ui_story_5014_50140201_50_dialog_content = "PlayerName กำแพงหินนี่นำทางไปข้างบน... แล้วก็มีแสงสว่างอยู่บนนั้นด้วย!",
  ui_story_5014_50140201_51_dialog_content = "ต้องเป็นทางออกแน่ คาร์ลีน เราเจอทางออกแล้ว!",
  ui_story_5014_50140201_52_dialog_content = "ยอดเลย...",
  ui_story_5014_50140201_53_dialog_content = "คาร์ลีน เดี๋ยวฉันช่วยเอง ระวังนะ... ขึ้นไปกันเถอะ",
  ui_story_5014_50140201_54_dialog_content = "เดี๋ยวฉันช่วยอีกแรง",
  ui_story_5014_50140201_55_dialog_content = "<color=#e8d9bb>ซวบ ซวบ</color>",
  ui_story_5014_50140201_56_dialog_content = "เหมือนจะมีฝาอยู่ข้างบนแฮะ!",
  ui_story_5014_50140201_57_dialog_content = "ฝาเหรอ? ต้องมีคนทำขึ้นมาสิ... คนที่เราตามหาอาจจะอยู่ข้างบนก็ได้!",
  ui_story_5014_50140201_58_dialog_content = "PlayerName ขอฉันหาวิธีเปิดก่อนนะ...",
  ui_story_5014_50140201_59_dialog_content = "<color=#e8d9bb>เอี๊ยด... ครืด...</color>",
  ui_story_5014_50140201_60_dialog_content = "<color=#e8d9bb>ฟิ้ววว...</color>",
  ui_story_5014_50140201_61_dialog_content = "เรา...",
  ui_story_5014_50140201_62_dialog_content = "เราอยู่ที่ไหนกันเนี่ย?!",
  ui_story_5014_50140201_63_dialog_content = "ไวซ์... นี่ฉันฝันไปรึเปล่า?",
  ui_story_5014_50140201_64_dialog_content = "จ-ใจเย็นก่อนนะ คาร์ลีน",
  ui_story_5014_50140201_65_dialog_content = "ที่นี่อากาศอบอุ่น... ท้องฟ้าก็สดใส...",
