  ui_story_5014_50140201_67_dialog_content = "ฉันว่า...",
  ui_story_5014_50140201_68_dialog_content = "PlayerName นายเห็นอาคารสูงพวกนี้มั้ย?",
  ui_story_5014_50140201_69_dialog_content = "เห็นสิ... เราไม่ได้ฝันไปใช่มั้ย...?",
