  ui_story_5014_50140201_71_dialog_content = "ฉันจะไปสำรวจ!",
  ui_story_5014_50140201_72_dialog_content = "<color=#e8d9bb>คลิก... คลิก...</color>",
  ui_story_5014_50140201_73_dialog_content = "เดี๋ยวก่อน ไวซ์ มีเสียงประหลาดดังมาจากทางโน้น",
