  ui_story_5014_50140201_75_dialog_content = "<color=#e8d9bb>คลิก... คลิก...</color>",
  ui_story_5014_50140201_76_dialog_content = "นี่อะไรน่ะ?",
  ui_story_5014_50140201_77_dialog_content = "บี๊ป... บี๊ป...",
  ui_story_5014_50140201_78_dialog_content = "เป็นอุปกรณ์ที่น่าสงสัยจัง",
  ui_story_5014_50140201_79_dialog_content = "แถมยังส่งเสียงแปลก ๆ ไม่หยุด",
  ui_story_5014_50140201_80_dialog_content = "อย่าเข้าใกล้มันจะดีกว่า",
  ui_story_5014_50140201_81_dialog_content = "มันคือหุ่นยนต์น่ะ",
  ui_story_5014_50140201_82_dialog_content = "แต่ก็ไม่ได้เหมือนของอิลลูมินาซะทีเดียว...",
  ui_story_5014_50140201_83_dialog_content = "ความรู้สึกที่คุ้นเคยนี่ ทำให้ฉันนึกถึงหิ่งห้อยบนโคลอสซัสเลยแฮะ",
  ui_story_5014_50140201_84_dialog_content = "โปรดเตรียมตัวรับการตรวจสอบ",
  ui_story_5014_50140201_85_dialog_content = "มันส่งเสียงแล้วก็ยิงลำแสงได้ด้วย!",
  ui_story_5014_50140201_86_dialog_content = "ไม่ต้องห่วง มันแค่บอกว่าจะ \"ตรวจสอบ\" เรา",
  ui_story_5014_50140201_87_dialog_content = "ดังนั้นการเคลื่อนที่และลำแสงสแกนควรเป็นเพียงส่วนหนึ่งของการตรวจสอบ",
  ui_story_5014_50140201_88_dialog_content = "อยากรู้จังว่ากลไกการสแกนเป็นยังไง? ขอดูใกล้ ๆ ได้มั้ยนะ...",
  ui_story_5014_50140201_89_dialog_content = "คำเตือน! คำเตือน! พบบุคคลน่าสงสัยที่ละเมิด<color=#FFB400>ระเบียบการแต่งกาย</color>",
  ui_story_5014_50140201_90_dialog_content = "ดำเนินมาตรการปราบปรามและจับกุม!",
  ui_story_5014_50140201_91_dialog_content = "ไวซ์ PlayerName อยู่ห่างเจ้านั่นไว้นะ!",
  ui_story_5014_50140202_1_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5014_50140202_2_dialog_content = "อุ๊บ เผลอทำพังซะแล้ว",
  ui_story_5014_50140202_3_dialog_content = "ทำไมจู่ ๆ มันถึงโจมตีเราล่ะ? แล้ว \"ระเบียบการแต่งกาย\" นี่มันคืออะไรกันนะ?",
  ui_story_5014_50140202_4_dialog_content = "เครื่องจักรพวกนี้อันตรายจริง ๆ",
  ui_story_5014_50140202_5_dialog_content = "ไม่ว่ามันจะมีจุดประสงค์อะไร พวกเราต้องระวังตัวให้มาก",
  ui_story_5014_50140202_6_dialog_content = "คำเตือน พบการกระทำที่ขัดขวางกระบวนการยุติธรรม ทำลายทรัพย์สินสาธารณะ... ขอกำลังเสริม",
  ui_story_5014_50140202_7_dialog_content = "ท่าไม่ดีแล้ว มันกำลังเรียกพวกมาเพิ่ม",
  ui_story_5014_50140202_8_dialog_content = "ในเมื่อเราไม่รู้สถานการณ์ เราก็ควรหลีกเลี่ยงการต่อสู้...",
  ui_story_5014_50140202_9_dialog_content = "งั้นหาที่ปลอดภัยซ่อนตัวกันมั้ย?",
  ui_story_5014_50140202_10_dialog_content = "...",
  ui_story_5014_50140202_11_dialog_content = "นั่นใครน่ะ? ออกมานะ!",
  ui_story_5014_50140202_12_dialog_content = "ใจเย็นก่อน เราอยู่ฝ่ายเดียวกัน",
  ui_story_5014_50140202_13_dialog_content = "หาที่หลบกันก่อนเถอะ ก่อนที่หุ่นตัวอื่น ๆ จะแห่กันมา",
  ui_story_5014_50140202_14_dialog_content = "เดี๋ยวฉันจะอธิบายให้ฟังทีหลัง...",
  ui_story_5014_50140202_15_dialog_content = "แล้วคุณคือ...?",
  ui_story_5014_50140202_16_dialog_content = "เชอวาน นักวิจัยจากอิลลูมินา ภายใต้บังคับบัญชาของเจ้าหน้าที่วิทยาการกรอนรู",
  ui_story_5014_50140202_17_dialog_content = "อิลลูมินาเป็นผู้ผลิตธนูที่เธอใช้อยู่นะ รู้มั้ย",
  ui_story_5014_50140202_18_dialog_content = "ร้อยโทไวซ์",
  ui_story_5014_50140202_19_dialog_content = "ส่วนสหายทั้งสองคน คงจะเป็นเคเลสไทต์กับเจ้าหญิงแห่งลูโมโพลิสสินะ",
  ui_story_5014_50140202_20_dialog_content = "<size=45>อาจารย์เชอวาน?!</size>",
  ui_story_5014_50140202_21_dialog_content = "ใช่ ฉันเอง เพราะงั้นไม่ต้องตกใจไป",
  ui_story_5014_50140202_22_dialog_content = "ขอโทษนะคะ พอคุณใส่ผ้าปิดปากแบบนั้นแล้วฉันจำไม่ได้เลย",
  ui_story_5014_50140202_23_dialog_content = "แล้วคุณก็ดู... เปลี่ยนไปนิดหน่อยด้วย...",
  ui_story_5014_50140202_24_dialog_content = "นี่เป็นเสื้อผ้าชุดใหม่น่ะ",
  ui_story_5014_50140202_25_dialog_content = "แล้วฉันก็มีชุดให้พวกเธอด้วยนะ รอตรงนี้ก่อน เดี๋ยวจะไปเอามาให้",
  ui_story_5014_50140202_26_dialog_content = "อาจารย์ของเธอมาทำอะไรที่นี่น่ะ?",
  ui_story_5014_50140202_27_dialog_content = "อาจารย์เชอวานเป็นผู้เชี่ยวชาญเรื่องโบราณสถาน เธออาจจะมาสำรวจที่นี่ล่ะมั้ง",
  ui_story_5014_50140202_28_dialog_content = "เชี่ยวชาญเรื่องโบราณสถาน? เป็นครูสอนประวัติศาสตร์งั้นเหรอ?",
  ui_story_5014_50140202_29_dialog_content = "ผิดแล้ว เธอสอนโบราณคดี เป็นศาสตร์คนละแบบกับวิชาประวัติศาสตร์ของลูโมโพลิสเลยล่ะ",
  ui_story_5014_50140202_30_dialog_content = "ฉันเรียนรู้ทักษะการสำรวจทุกอย่างมาจากอาจารย์เชอวาน",
  ui_story_5014_50140202_31_dialog_content = "แต่ก่อนฝีมือเขียนแบบของฉันยังอ่อนด้อย ก็ได้คำวิจารณ์ของเธอนี่แหละที่ช่วยพัฒนาให้ดีขึ้น",
  ui_story_5014_50140202_32_dialog_content = "เข้าใจแล้ว ไม่แปลกใจเลยที่เธอเคารพอาจารย์ตัวเองขนาดนี้ คงเป็นความกลัวสินะ?",
  ui_story_5014_50140202_33_dialog_content = "เปล่านะ ฉันเคารพเธออย่างสุดหัวใจ ที่ฉันได้รู้จักกับวิทยาการโบราณก็เพราะเธอ",
  ui_story_5014_50140202_34_dialog_content = "ฉันมีแต่จะต้องขอบคุณเธอ ไม่เห็นจะต้องกลัวเลย!",
  ui_story_5014_50140202_35_dialog_content = "หลังจากได้ฟังคำวิจารณ์ ทักษะการเขียนแบบเทคนิคของฉันก็พัฒนาขึ้นมาก...",
  ui_story_5014_50140202_36_dialog_content = "แต่ก่อนฉันเข้มงวดกับเธอขนาดนั้นเลยรึ?",
  ui_story_5014_50140202_37_dialog_content = "โอ๊ะ คุณกลับมาแล้ว... ก็ไม่ขนาดนั้นหรอกค่ะ ไม่ต้องกังวลนะคะ",
  ui_story_5014_50140202_38_dialog_content = "ทำตัวตามสบายเถอะ ไม่ต้องเกร็งขนาดนั้นก็ได้",
  ui_story_5014_50140202_39_dialog_content = "ค่ะ... ขอโทษนะคะ ฉันไม่นึกว่าคุณจะยังจำฉันได้ ก็เลยประหม่านิดหน่อย",
  ui_story_5014_50140202_40_dialog_content = "ฉันอ่านรายงานเรื่องโคลอสซัสของเธอทุกเล่ม แล้วฉันก็ประทับใจมาก",
  ui_story_5014_50140202_41_dialog_content = "ฉันดีใจที่เธอเลือกเดินในสายงานวิทยาการโบราณนะ",
  ui_story_5014_50140202_42_dialog_content = "ขอบคุณค่ะ ที่จริงตัวฉันเองก็สนใจวิทยาการโบราณมาตลอดอยู่แล้ว",
  ui_story_5014_50140202_43_dialog_content = "ที่ฉันพูดแบบนั้นก็เพราะความสามารถของเธอมันโดดเด่นจริง ๆ",
  ui_story_5014_50140202_44_dialog_content = "เธอลงมาที่นี่ได้ยังไง?",
  ui_story_5014_50140202_45_dialog_content = "เราได้รับสัญญาณไม่ทราบที่มาระหว่างขับโคลอสซัสครับ",
  ui_story_5014_50140202_46_dialog_content = "ไวซ์เป็นคนถอดรหัสพิกัด แล้วมันก็อยู่ใกล้กับเราพอดี",
  ui_story_5014_50140202_47_dialog_content = "เกิดแผ่นดินไหวระหว่างที่เราเดินสำรวจ เราก็เลยตกลงมาในรอยร้าว แล้วก็มาลงเอยในถ้ำนี้...",
  ui_story_5014_50140202_48_dialog_content = "แล้วพวกเราก็เดินมาจนถึงนี่ค่ะ",
  ui_story_5014_50140202_49_dialog_content = "เป็นอย่างที่ฉันกลัวจริง ๆ สัญญาณขอความช่วยเหลือของฉันส่งไปไม่ถึงข้างนอก",
  ui_story_5014_50140202_50_dialog_content = "แล้วสัญญาณที่เราได้รับล่ะครับ?",
  ui_story_5014_50140202_51_dialog_content = "นั่นไม่ใช่ของฉันน่ะสิ",
  ui_story_5014_50140202_52_dialog_content = "ฉันเองก็ได้สัญญาณพิกัดนั่นตอนออกลาดตระเวนตามปกติในแถบภูเขาของนอร์ธแลนด์",
  ui_story_5014_50140202_53_dialog_content = "แล้วการค้นหาก็พาพวกเรามาที่นี่เช่นกัน",
  ui_story_5014_50140202_54_dialog_content = "มีบางอย่างรบกวนสัญญาณขอความช่วยเหลือ แล้วอุปกรณ์สื่อสารของฉันก็พัง",
  ui_story_5014_50140202_55_dialog_content = "\"พวกเรา\"? แล้วเพื่อนคุณอยู่ไหนเหรอคะ?",
  ui_story_5014_50140202_56_dialog_content = "ปกติฉันทำงานคนเดียวตลอด พวกนั้นไม่ใช่ทีมของฉันหรอก",
