  ui_story_5014_50140701_52_dialog_content = "ซูเปอร์มาร์เก็ต คืออะไรน่ะ?",
  ui_story_5014_50140701_53_dialog_content = "อ๋อ ที่นั่นมีของทุกอย่าง อยากจะหยิบอะไรก็ได้ทั้งนั้น",
  ui_story_5014_50140701_54_dialog_content = "การทำงานทุกขั้นตอนเป็นระบบอัตโนมัติหมดเลย... นี่มันเกินความเข้าใจของพวกเราไปแล้ว...",
  ui_story_5014_50140701_55_dialog_content = "นี่คือวิทยาการอัตโนมัติของโลกยุคโบราณเหรอเนี่ย... เหลือเชื่อจริง ๆ",
  ui_story_5014_50140701_56_dialog_content = "แล้วชีวิตประจำวันของพวกเธอเป็นยังไงเหรอ?",
  ui_story_5014_50140701_57_dialog_content = "อืม ก็ปกติล่ะมั้ง...?",
  ui_story_5014_50140701_58_dialog_content = "งั้นถามเจาะจงกว่านี้หน่อยละกัน ถ้าเสื้อผ้าสกปรกเธอจะทำยังไง?",
  ui_story_5014_50140701_59_dialog_content = "ก็แค่เอาไปใส่เครื่องซักผ้า เดี๋ยวมันก็จะซักให้เราเอง",
  ui_story_5014_50140701_60_dialog_content = "แล้วถ้าเธออยากอาบน้ำล่ะ?",
  ui_story_5014_50140701_61_dialog_content = "ก็แค่บอกบัตเลอร์ เดี๋ยวพวกหุ่นยนต์ก็จะอุ่นน้ำให้",
  ui_story_5014_50140701_62_dialog_content = "แล้วถ้าเธออยากทำความสะอาดห้องล่ะ?",
  ui_story_5014_50140701_63_dialog_content = "ก็บอกบัตเลอร์ แล้วพวกหุ่นยนต์ก็จะมาทำความสะอาดให้",
  ui_story_5014_50140701_64_dialog_content = "แล้วถ้าอยากอ่านหนังสือล่ะ?",
  ui_story_5014_50140701_65_dialog_content = "ก็บอกบัตเลอร์ เดี๋ยวพวกหุ่นยนต์ก็จะมาเล่นคอนเทนต์ให้ดู",
  ui_story_5014_50140701_66_dialog_content = "แล้วเวลาที่เธอต้องทำงานหรือเขียนรายงานล่ะ?",
  ui_story_5014_50140701_67_dialog_content = "งาน? รายงาน? นั่นมันหน้าที่ของหุ่นยนต์ไม่ใช่เหรอ?",
  ui_story_5014_50140701_68_dialog_content = "ให้ตายสิ นี่มันเป็นชีวิตที่วิเศษสุด ๆ!",
  ui_story_5014_50140701_69_dialog_content = "น่ากลัวชะมัด อยู่เฉย ๆ ไม่ต้องทำอะไรทั้งนั้น ไม่ต่างจากถูกเลี้ยงในคอกเลยนะ...",
