  ui_story_5014_50140702_51_dialog_content = "<color=#e8d9bb>ออโรเรียนอย่างพวกคุณช่างน่าสนใจจริง ๆ</color>",
  ui_story_5014_50140702_52_dialog_content = "นายก็เหมือนกัน... นับวันชักจะพูดเหมือนพวกเราเข้าไปทุกทีแล้วนะ",
  ui_story_5014_50140702_53_dialog_content = "<color=#e8d9bb>ผมคือปัญญาประดิษฐ์ที่มีความสามารถในการเรียนรู้</color>",
  ui_story_5014_50140702_54_dialog_content = "คงไม่ได้เรียนวิธีบัญชาการรบมาจากซีมัสด้วยหรอกนะ...",
  ui_story_5014_50140702_55_dialog_content = "PlayerName ฉันกับฟลอรีนจะเฝ้าแนวหลังให้ พาทุกคนฝ่าวงล้อมออกไป เร็วเข้า!",
  ui_story_5014_50140702_56_dialog_content = "เอริก้า ปกป้ององค์หญิงคาร์ลีนด้วย!",
  ui_story_5014_50140702_57_dialog_content = "ค่ะ ประธาน",
  ui_story_5014_50140702_58_dialog_content = "เข้าใจแล้วครับ ผมจะสั่งการให้เอง",
  ui_story_5014_50140801_1_dialog_content = "เอาไงดีล่ะ? พวกหุ่นยนต์เข้ามาใกล้ขึ้นเรื่อย ๆ แล้วนะ",
  ui_story_5014_50140801_2_dialog_content = "วิ่งให้เร็วกว่านี้ไงล่ะ เราอุตส่าห์สู้แทบตายเพื่อฝ่าวงล้อมออกมา...",
  ui_story_5014_50140801_3_dialog_content = "<color=#e8d9bb>ครืน!</color>",
  ui_story_5014_50140801_4_dialog_content = "แผ่นดินไหวอีกแล้ว ระวังหินหล่นลงมานะ!",
  ui_story_5014_50140801_5_dialog_content = "มีที่ว่างอยู่ตรงโน้น ฉันจะนำทางให้เอง",
  ui_story_5014_50140801_6_dialog_content = "<size=30><color=#e8d9bb>ตูม...</color></size>",
  ui_story_5014_50140801_7_dialog_content = "<color=#e8d9bb>ระวัง... ดิน...</color>",
  ui_story_5014_50140801_8_dialog_content = "<color=#e8d9bb>บี๊ป... บี๊ป...</color>",
  ui_story_5014_50140801_9_dialog_content = "หุ่นยนต์ชั่วร้ายพังแล้ว",
  ui_story_5014_50140801_10_dialog_content = "คุณเชอวานบอกว่าแผ่นดินไหวอาจส่งผลกระทบกับศูนย์ปฏิบัติงานต่าง ๆ ที่นี่",
  ui_story_5014_50140801_11_dialog_content = "บัตเลอร์นั่นอาจจะสูญเสียการควบคุมเครื่องจักรชั่วคราว...",
  ui_story_5014_50140801_12_dialog_content = "<color=#e8d9bb>ซ่า... ซ่า</color>",
  ui_story_5014_50140801_13_dialog_content = "เครื่องสื่อสารของฉันเจออะไรอีกแล้ว",
  ui_story_5014_50140801_14_dialog_content = "สัญญาณเดิมของซีมัสรึเปล่า?",
  ui_story_5014_50140801_15_dialog_content = "ไม่ใช่นะ เป็นสัญญาณที่เข้ารหัสไว้ ฉันจะต้องถอดรหัสให้ได้ก่อน",
  ui_story_5014_50140801_16_dialog_content = "มันต่างกันตรงไหนน่ะ? อันที่แล้วก็เข้ารหัสไม่ใช่เหรอ",
  ui_story_5014_50140801_17_dialog_content = "เครื่องสื่อสารของทีมสำรวจอิลลูมินาส่งข้อมูลเข้ารหัสให้กันและกันได้...",
  ui_story_5014_50140801_18_dialog_content = "สัญญาณตอนที่เราเจอวาเลนเซียนั่นเป็นสัญญาณบอกพิกัด แต่คราวนี้เป็นการประกาศข้อมูล",
  ui_story_5014_50140801_19_dialog_content = "แผ่นดินไหวเมื่อกี้น่าจะทำให้ฟังก์ชันประกาศข้อมูลในอุปกรณ์ของซีมัสทำงาน",
  ui_story_5014_50140801_20_dialog_content = "ซีมัสอยากจะบอกอะไรให้ทุกคนรู้กันนะ?",
  ui_story_5014_50140801_21_dialog_content = "ฉันเองก็ไม่ชินกับระบบเข้ารหัสเท่าไหร่ แต่ทีมสำรวจมีกุญแจถอดรหัสกลาง ฉันเลยพอจะแกะข้อความมาได้ส่วนนึง",
  ui_story_5014_50140801_22_dialog_content = "รอแป๊บนึงนะ!",
  ui_story_5014_50140801_23_dialog_content = "<size=30><color=#e8d9bb>ครืนน...</color></size>",
  ui_story_5014_50140801_24_dialog_content = "ไวซ์ ได้ความอะไรบ้างมั้ย?",
  ui_story_5014_50140801_25_dialog_content = "เป็นข้อมูลสั้น ๆ ที่ไม่ต่อเนื่องกัน บันทึกไว้ในช่วงเวลาต่าง ๆ",
  ui_story_5014_50140801_26_dialog_content = "เดี๋ยวจะอ่านให้ฟังนะ...",
  ui_story_5014_50140801_27_dialog_content = "ตอนแรก เขาพูดถึงสงครามในสมัยโบราณ",
  ui_story_5014_50140801_28_dialog_content = "ที่นี่เคยมีคนรบกันด้วยเหรอ? ไม่เห็นเคยรู้เลย...",
  ui_story_5014_50140801_29_dialog_content = "เป็นเรื่องที่เกิดขึ้นมานานมากแล้วน่ะ สงครามโบราณนั่นไม่เคยมีการบันทึกในเอกสารประวัติศาสตร์ฉบับไหนเลย",
  ui_story_5014_50140801_30_dialog_content = "แต่นักประวัติศาสตร์หลายคนปักใจเชื่อว่ามันเคยเกิดขึ้นจริงแน่นอน",
  ui_story_5014_50140801_31_dialog_content = "ซีมัสบอกว่าเมืองแห่งนี้เป็นซากของที่หลบภัยขนาดใหญ่ที่มนุษย์สมัยโบราณสร้างขึ้น",
  ui_story_5014_50140801_32_dialog_content = "เป้าหมายในการสร้างเมืองก็เพื่อจะหลบหนีจากการสู้รบ หรือไม่ก็เพื่อป้องกันไม่ให้เกิดภัยพิบัติอื่นตามมา",
  ui_story_5014_50140801_33_dialog_content = "\"อย่างไรก็ตาม มนุษย์โบราณเหล่านั้นก็สูญสิ้นไป เหลือไว้แต่ปัญญาประดิษฐ์ที่เรียกว่าบัตเลอร์\"",
  ui_story_5014_50140801_34_dialog_content = "\"มันมีหน้าที่ควบคุมดูแลศูนย์ปฏิบัติงานทุกอย่างในนี้ และปฏิเสธที่จะตอบคำถามทุกเรื่องที่เกี่ยวข้องกับอดีต\"",
  ui_story_5014_50140801_35_dialog_content = "\"มิติและเวลาของที่แห่งนี้แปลกประหลาดมาก ฉันยังไม่ทราบเหตุผลแน่ชัด\"",
  ui_story_5014_50140801_36_dialog_content = "ส่วนต่อจากนี้ฉันถอดรหัสไม่ได้แล้ว เขาใช้ระบบเข้ารหัสหลายชั้นที่ซับซ้อนมาก",
  ui_story_5014_50140801_37_dialog_content = "ทำไมต้องทำให้มันยุ่งยากด้วยล่ะ?",
  ui_story_5014_50140801_38_dialog_content = "การเข้ารหัสข้อมูลทำเพื่อความปลอดภัย มันคงเป็นข้อมูลที่สำคัญมาก ๆ",
  ui_story_5014_50140801_39_dialog_content = "ฉันต้องบันทึกไว้และเอากลับไปที่อิลลูมินา เพื่อให้คุณเชอวานถอดรหัส",
  ui_story_5014_50140801_40_dialog_content = "ก็ดี แล้วซีมัสส่งข้อมูลอย่างอื่นอีกมั้ย?",
  ui_story_5014_50140801_41_dialog_content = "ในส่วนที่สองของประกาศ เขาบันทึกเรื่องราวที่ตัวเขาได้พบกับหญิงสาวจากลูโมโพลิส ก่อนที่จะตกลงมาในนี้",
  ui_story_5014_50140801_42_dialog_content = "\"ระหว่างออกสำรวจในทุ่งหิมะ ฉันได้เจอหญิงสาวคนหนึ่งจากลูโมโพลิส\"",
  ui_story_5014_50140801_43_dialog_content = "\"พวกเราถูกอิคลิพไซท์จู่โจม ก็เลยเจอเมืองแห่งนี้โดยบังเอิญ\"",
  ui_story_5014_50140801_44_dialog_content = "หญิงสาวคนนั้นคงจะเป็นภรรยาของเขาสินะ?",
  ui_story_5014_50140801_45_dialog_content = "ใช่ พอรู้ว่าต้องติดอยู่ในนี้ พวกเขาก็ตัดสินใจร่วมมือกันสำรวจที่นี่...",
  ui_story_5014_50140801_46_dialog_content = "\"เมืองนี้ไม่มีโรงงานสำหรับผลิตอาวุธ และการปกป้องจากบัตเลอร์ก็ไม่ได้มีประสิทธิภาพนัก\"",
  ui_story_5014_50140801_47_dialog_content = "\"โชคดีที่เราสามารถซ่อมแซมโมดูลชีวเคมีของระบบได้\"",
  ui_story_5014_50140801_48_dialog_content = "\"บัตเลอร์เรียกมันว่าแอ๊บบี้ และมันก็ช่วยให้เรารอดชีวิตจากวิกฤตอิคลิพไซท์\"",
  ui_story_5014_50140801_49_dialog_content = "โมดูลชีวเคมีคืออะไรน่ะ? แล้วคำว่าแอ๊บบี้นั่น เป็นชื่องั้นเหรอ?",
  ui_story_5014_50140801_50_dialog_content = "อาจจะหมายถึงโมดูลชีวภาพก็ได้มั้ง แต่ฉันก็ไม่รู้ว่ามันคืออะไรอยู่ดีแฮะ",
  ui_story_5014_50140801_51_dialog_content = "ส่วนต่อไปบันทึกไว้หลังจากนั้นหลายปีเลย...",
  ui_story_5014_50140801_52_dialog_content = "\"อิคลิพไซท์มีจำนวนเพิ่มขึ้นอย่างต่อเนื่อง เราไม่แน่ใจว่าพวกมันเข้ามาได้ยังไง\"",
  ui_story_5014_50140801_53_dialog_content = "\"แต่บัตเลอร์ปฏิเสธที่จะตอบคำถามนี้\"",
  ui_story_5014_50140801_54_dialog_content = "\"ฉันต้องการวิธีที่มีประสิทธิภาพในการกำจัดผู้บุกรุก ถ้าฉันหาทางออกเจอก็คงจะดี\"",
  ui_story_5014_50140801_55_dialog_content = "\"บัตเลอร์คอยจับตามองฉันอยู่ตลอด ฉันจะต้องซ่อนตัว\"",
  ui_story_5014_50140801_56_dialog_content = "\"สหายร่วมรบ หวังว่าคุณจะได้รับข้อความนี้...\"",
  ui_story_5014_50140801_57_dialog_content = "แล้วก็ยังมีอีกนะ...",
  ui_story_5014_50140801_58_dialog_content = "\"ตอนที่คุณได้อ่านข้อความนี้ ฉันอาจจะตายไปแล้ว\"",
  ui_story_5014_50140801_59_dialog_content = "\"แต่ฉันก็หาวิธีปกป้องพวกเธอได้ ฉันทำสัญญากับบัตเลอร์เอาไว้...\"",
  ui_story_5014_50140801_60_dialog_content = "\"ภรรยากับลูกสาวของฉันจะได้ใช้ชีวิตอยู่ที่นี่ต่อไปอย่างปลอดภัย\"",
  ui_story_5014_50140801_61_dialog_content = "\"ช่วยดูแลพวกเขาแทนฉันด้วย... ได้โปรด พาพวกเขาออกไปจากเมืองนี้ที\"",
  ui_story_5014_50140801_62_dialog_content = "\"ฉันทิ้งข้อมูลบางอย่างไว้ในห้องของฉัน พิกัดก็คือ...\"",
  ui_story_5014_50140801_63_dialog_content = "พิกัดคือที่ไหนเหรอ?",
  ui_story_5014_50140801_64_dialog_content = "อืมม... โทษทีนะ... ฉันถอดรหัสออกมาไม่ได้น่ะ",
  ui_story_5014_50140801_65_dialog_content = "แล้วเขาว่ายังไงอีกบ้าง?",
  ui_story_5014_50140801_66_dialog_content = "คำพูดสุดท้ายของเขาคือ \"เพื่อนร่วมชาติและสหายร่วมรบแห่งอิลลูมินา... ฉันขอฝากทุกอย่างด้วย\"",
  ui_story_5014_50140801_67_dialog_content = "\"ขออิลลูมินาจงเจิดจำรัส!\"",
  ui_story_5014_50140801_68_dialog_content = "แค่นี้เหรอ?",
  ui_story_5014_50140801_69_dialog_content = "ใช่ นี่คือทุกอย่างที่ฉันถอดรหัสได้จากประกาศข้อมูล",
  ui_story_5014_50140801_70_dialog_content = "<size=30><color=#e8d9bb>ครืนน...</color></size>",
  ui_story_5014_50140801_71_dialog_content = "อาฟเตอร์ช็อกอีกแล้ว.. คุณเชอวานจะเป็นยังไงบ้างนะ...",
  ui_story_5014_50140801_72_dialog_content = "อืมม...",
  ui_story_5014_50140801_73_dialog_content = "ไม่ต้องห่วง ไวซ์บอกว่าอาจขัดขวางการควบคุมหุ่นยนต์ของบัตเลอร์",
  ui_story_5014_50140801_74_dialog_content = "สองคนนั้นน่าจะกำจัดพวกหุ่นได้ในเวลาไม่นาน เดี๋ยวพวกเราก็ได้เจอกัน",
  ui_story_5014_50140801_75_dialog_content = "ขอบคุณที่ปลอบฉันนะคะ... องค์หญิง",
  ui_story_5014_50140801_76_dialog_content = "<color=#e8d9bb>หยุด... การดิ้นรน... ที่เปล่าประโยชน์...</color>",
  ui_story_5014_50140801_77_dialog_content = "<color=#e8d9bb>ยอมแพ้... ได้แล้ว</color>",
  ui_story_5014_50140801_78_dialog_content = "ฟลอรีน จังหวะนี้ล่ะ!",
  ui_story_5014_50140801_79_dialog_content = "รู้แล้วน่า ไม่ต้องบอกหรอก",
  ui_story_5014_50140801_80_dialog_content = "พบกับการลงโทษ Wrath of Razer!",
  ui_story_5014_50140801_81_dialog_content = "<color=#e8d9bb>ซ่า! ตูม!</color>",
  ui_story_5014_50140801_82_dialog_content = "<color=#e8d9bb>น-นี่คือลูมินาติกส์ของคุณรึนี่?</color>",
  ui_story_5014_50140801_83_dialog_content = "<color=#e8d9bb>น่าสนใจ... คู่ควรแก่การศึกษา</color>",
  ui_story_5014_50140801_84_dialog_content = "น่าหงุดหงิดชะมัด! มันย้ายไปที่หุ่นอีกตัวแล้ว",
  ui_story_5014_50140801_85_dialog_content = "ตราบใดที่มันยังสั่งการหุ่นพวกนี้ได้ เราก็ต้องสู้กับพวกมันไม่มีวันจบ",
  ui_story_5014_50140801_86_dialog_content = "ฉันว่าถ้ามีโอกาสเรารีบฝ่าออกไปเถอะ",
  ui_story_5014_50140801_87_dialog_content = "มันไม่ง่ายแบบนั้นน่ะสิ เจ้าบัตเลอร์นั่นตั้งใจปล่อยคาร์ลีนไป แต่จับตามองเราอย่างใกล้ชิด...",
  ui_story_5014_50140801_88_dialog_content = "บัตเลอร์ นายคงไม่อยากให้ฉันอ่านข้อความของซีมัสสินะ?",
  ui_story_5014_50140801_89_dialog_content = "<color=#e8d9bb>ความปลอดภัยของเมืองนี้เป็นสิ่งสำคัญที่สุดสำหรับผม</color>",
  ui_story_5014_50140801_90_dialog_content = "เข้าใจแล้ว เพื่อความปลอดภัยของข้อมูลสินะ",
  ui_story_5014_50140801_91_dialog_content = "ถ้ามัวชักช้าต่อไปเราแย่แน่",
  ui_story_5014_50140801_92_dialog_content = "คุณสังเกตรึเปล่า? ว่าหุ่นพวกนี้มันแข็งแกร่งขึ้นน่ะ",
  ui_story_5014_50140801_93_dialog_content = "ใช่ พวกมันเรียนรู้วิธีการต่อสู้ของพวกเรา",
  ui_story_5014_50140801_94_dialog_content = "คุณไม่คิดว่ามันน่ากลัวหรือไง?",
  ui_story_5014_50140801_95_dialog_content = "ถ้าปล่อยให้ปัญญาประดิษฐ์พัฒนาไปเรื่อย ๆ แบบนี้ สักวันนึงมันจะมีพลังมากพอที่จะทำลายออโรเรียน",
  ui_story_5014_50140801_96_dialog_content = "ฉันเข้าใจเธอนะ แต่เราหนีไปจากที่นี่ก่อนเถอะ",
  ui_story_5014_50140801_97_dialog_content = "<color=#e8d9bb>คุณ... ไปไหนไม่ได้ทั้งนั้น</color>",
  ui_story_5014_50140801_98_dialog_content = "<color=#e8d9bb>คุณ... หมดทางหนีแล้ว</color>",
  ui_story_5014_50140801_99_dialog_content = "<size=30><color=#e8d9bb>ครืนน...</color></size>",
  ui_story_5014_50140801_100_dialog_content = "มีอาฟเตอร์ช็อกอีกแล้ว โจมตีพร้อมกันนะ!",
  ui_story_5014_50140801_101_dialog_content = "ก็บอกแล้วไงคะ ฉันรู้ว่าต้องทำยังไง!",
  ui_story_5014_50140801_102_dialog_content = "<color=#e8d9bb>พวกคุณ... ซ่า...</color>",
  ui_story_5014_50140801_103_dialog_content = "ฝ่าวงล้อมได้แล้ว ไปกันเถอะ!",
  ui_story_5014_50140801_104_dialog_content = "แสดงว่าแผนถ่วงเวลาก็ใช้กับหุ่นยนต์ได้ผลเหมือนกันแฮะ",
  ui_story_5014_50140801_105_dialog_content = "คราวหน้าคงจะไม่ได้แล้วล่ะ",
  ui_story_5014_50140801_106_dialog_content = "จากนี้ต้องทำยังไงต่อ?",
  ui_story_5014_50140801_107_dialog_content = "เครื่องสื่อสารของฉันเพิ่งได้รับข้อมูลที่ซีมัสประกาศ มันกลับมาใช้งานได้แล้ว",
  ui_story_5014_50140801_108_dialog_content = "เราต้องหาที่ปลอดภัยเพื่อกลับไปรวมกลุ่มกับไวซ์",
  ui_story_5014_50140801_109_dialog_content = "ได้เลย ฉันจะส่งอัลบาไปหาตำแหน่งที่ไม่มีหุ่นยนต์",
  ui_story_5014_50140801_110_dialog_content = "เธอไปก่อนเถอะ ฉันต้องส่งข้อมูลให้วาเลนเซียสักหน่อย",
  ui_story_5014_50140801_111_dialog_content = "ทำไมต้องส่งด้วย?",
  ui_story_5014_50140801_112_dialog_content = "เด็กพวกนั้นเป็นลูกสาวของสหายร่วมรบ",
  ui_story_5014_50140801_113_dialog_content = "ซีมัสทิ้งข้อความไว้ ขอร้องให้เราดูแลลูกสาวของเขา",
  ui_story_5014_50140801_114_dialog_content = "ฉันจะไม่มีทางทิ้งพวกเธอไว้...",
  ui_story_5014_50140801_115_dialog_content = "<color=#e8d9bb>ซ่า... ซ่า...</color>",
  ui_story_5014_50140801_116_dialog_content = "บัตเลอร์ นายปล่อยพวกมันไปเหรอ?",
  ui_story_5014_50140801_117_dialog_content = "<color=#e8d9bb>สัญญาณ... ถูกขัดจังหวะ...</color>",
  ui_story_5014_50140801_118_dialog_content = "<color=#e8d9bb>เพื่อความปลอดภัย... ของคุณ...</color>",
  ui_story_5014_50140801_119_dialog_content = "<color=#e8d9bb>โปรด... ซ่อนตัว... ที่นี่</color>",
  ui_story_5014_50140801_120_dialog_content = "เราทำอะไรไม่ได้... ต้องรอให้บัตเลอร์ฟื้นตัว",
  ui_story_5014_50140801_121_dialog_content = "<color=#e8d9bb>ติ๊ก... ติ๊ก</color>",
  ui_story_5014_50140801_122_dialog_content = "พี่คะ ของดูต่างหน้าของพ่อ!",
  ui_story_5014_50140801_123_dialog_content = "ขอฉันดูหน่อย!",
  ui_story_5014_50140801_124_dialog_content = "<color=#e8d9bb>ซ่า... ซ่า...</color>",
  ui_story_5014_50140801_125_dialog_content = "\"วาเลนเซีย... เกร... ฉันรู้ว่าเธอจะ... ได้รับข้อความนี้\"",
  ui_story_5014_50140801_126_dialog_content = "ฉันอยากจะ... บอกเธอว่า...",
  ui_story_5014_50140801_127_dialog_content = "เราเป็น... สหายร่วมรบ... พ่อของเธอ... จะ... ปกป้องเธอ",
  ui_story_5014_50140801_128_dialog_content = "พาเธอ... กลับบ้าน... ไปที่อิลลูมินา",
  ui_story_5014_50140801_129_dialog_content = "ข้อความจากเชอวาน...",
  ui_story_5014_50140801_130_dialog_content = "ผู้หญิงคนนั้นน่ะนะ?",
  ui_story_5014_50140801_131_dialog_content = "ที่นี่คือบ้านของเรา จะต้องให้เธอพาไปที่อื่นทำไม!",
  ui_story_5014_50140901_1_dialog_content = "คุณเชอวานอยากให้พวกเราไปเจอกัน... ทางนี้...",
  ui_story_5014_50140901_2_dialog_content = "โอเค ฉันรู้ว่าทางไหนไม่มีศัตรู ตามฉันมา",
  ui_story_5014_50140901_3_dialog_content = "บี๊ป... บี๊ป",
  ui_story_5014_50140901_4_dialog_content = "มีหุ่นยนต์เฝ้าอยู่ตรงถนนข้างหน้า เราต้องอ้อมไป",
  ui_story_5014_50140901_5_dialog_content = "ทางนี้...",
  ui_story_5014_50140901_6_dialog_content = "บี๊ป... บี๊ป",
  ui_story_5014_50140901_7_dialog_content = "ทำไมเครื่องจักรพวกนี้มันคลั่งอีกแล้วล่ะเนี่ย?",
  ui_story_5014_50140901_8_dialog_content = "พี่รูบี้ ระวังนะคะ...",
  ui_story_5014_50140901_9_dialog_content = "<color=#e8d9bb>เปรี้ยง... เปรี้ยง!</color>",
  ui_story_5014_50140901_10_dialog_content = "จะกลัวอะไรน่ะ? เราจะจัดการพวกมันให้หมดนี่ล่ะ",
  ui_story_5014_50140901_11_dialog_content = "ทำแบบนั้นไม่ได้หรอก พี่รูบี้ ไปรุนแรงใส่มันก็ยิ่งทำให้พวกมันก้าวร้าว...",
  ui_story_5014_50140901_12_dialog_content = "ไวซ์กับคาร์ลีน มีออโรเรียนกำลังสู้กับหุ่นยนต์อยู่ข้างหน้า!",
  ui_story_5014_50140901_13_dialog_content = "จะเป็นประธานรึเปล่านะ?",
  ui_story_5014_50140901_14_dialog_content = "จู่ ๆ อย่าโผล่มาแบบนี้สิ ฉันตกใจนะ!",
  ui_story_5014_50140901_15_dialog_content = "ฉันรับสัญญาณของประธานไม่ได้เลย แล้วคุณล่ะ?",
  ui_story_5014_50140901_16_dialog_content = "(เธอคงหมายถึงโทรจิตล่ะมั้ง... ท่าทางเธอเป็นห่วงฟลอรีนน่าดูเลยนะเนี่ย)",
  ui_story_5014_50140901_17_dialog_content = "ไม่ใช่ฟลอรีน แต่เป็นออโรเรียนสองคนที่โดนหุ่นยนต์ล้อม",
  ui_story_5014_50140901_18_dialog_content = "มีคนอื่นติดอยู่ในนี้ด้วยเหรอเนี่ย? เราต้องช่วยพวกเธอ",
  ui_story_5014_50140901_19_dialog_content = "แต่ประธาน...",
  ui_story_5014_50140901_20_dialog_content = "ฟลอรีนสบายดี คุณเชอวานเพิ่งส่งข้อความมา",
  ui_story_5014_50140901_21_dialog_content = "ไวซ์ ติดต่อคุณเชอวานให้ทีสิ",
  ui_story_5014_50140901_22_dialog_content = "บอกพวกนั้นว่าเราขอช่วยออโรเรียนที่โดนล้อมก่อน เดี๋ยวจะตามไปทีหลัง",
  ui_story_5014_50140901_23_dialog_content = "ได้เลย",
  ui_story_5014_50140901_24_dialog_content = "บี๊ป... โปรดหยุดทำลาย โปรด...",
  ui_story_5014_50140901_25_dialog_content = "หุบปากน่า ไปให้พ้น!",
  ui_story_5014_50140901_26_dialog_content = "อู... แคว้ก!",
  ui_story_5014_50140901_27_dialog_content = "บ้าเอ๊ย! กลายเป็นว่าเราดึงดูดอิคลิพไซท์ให้มาทางนี้!",
  ui_story_5014_50140901_28_dialog_content = "ไม่ใช่แค่อิคลิพไซท์นะ ดูโน่นสิ",
  ui_story_5014_50140901_29_dialog_content = "นั่นมันคนนี่นา...",
  ui_story_5014_50140901_30_dialog_content = "เธอคือเจ้าหญิงคาร์ลีนผู้เลื่องชื่อ!",
  ui_story_5014_50140901_31_dialog_content = "คาร์ลีน นั่นคนรู้จักเธอเหรอ?",
  ui_story_5014_50140901_32_dialog_content = "... ไม่ใช่นะ เรากำจัดศัตรูกันก่อนเถอะ",
  ui_story_5014_50140902_1_dialog_content = "วงสวิงสุดแรงเกิด!",
  ui_story_5014_50140902_2_dialog_content = "เดี๋ยว อย่าเล็งมาทางนี้สิ!",
  ui_story_5014_50140902_3_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5014_50140902_4_dialog_content = "PlayerName!!",
  ui_story_5014_50140902_5_dialog_content = "หวา... เขาหมดสติไปแล้ว",
  ui_story_5014_50140902_6_dialog_content = "ถ้าเธอกล้าทำร้ายเคเลสไทต์ ฉันไม่ปล่อยเธอไว้แน่",
  ui_story_5014_50140902_7_dialog_content = "โทษทีนะ... ฉันเห็นอิคลิพไซท์อยู่ใกล้ ๆ เขา ก็เลย...",
  ui_story_5014_50140902_8_dialog_content = "แต่อย่างน้อยก็ไม่โดนนี่นะ",
  ui_story_5014_50140902_9_dialog_content = "คราวหน้าพยายามคุมท่าโจมตีตัวเองหน่อยสิ!",
  ui_story_5014_50140902_10_dialog_content = "ขอโทษด้วยนะคะ พี่รูบี้เป็นคนมือหนักแบบนี้แหละ...",
  ui_story_5014_50140902_11_dialog_content = "ฉันเคยฝึกวิชาการแพทย์มาก่อน เดี๋ยวจะดูอาการให้นะ...",
  ui_story_5014_50140902_12_dialog_content = "PlayerName เป็นยังไงบ้าง?",
  ui_story_5014_50140902_13_dialog_content = "ก็ดูท่าทางไม่เป็นไรนะ อีกเดี๋ยวก็คงฟื้น...",
  ui_story_5014_50140902_14_dialog_content = "โอย... ปวดหัวจัง...",
  ui_story_5014_50140902_15_dialog_content = "ฟื้นแล้วเหรอ?",
  ui_story_5014_50140902_16_dialog_content = "เอ่อ... พวกคุณมานี่ตั้งแต่เมื่อไหร่น่ะ?",
  ui_story_5014_50140902_17_dialog_content = "แล้ว... ทุกอย่างเรียบร้อยดีใช่มั้ยครับ?",
  ui_story_5014_50140902_18_dialog_content = "ฉันกับคุณเชอวานสบายดี ไม่ต้องห่วง",
  ui_story_5014_50140902_19_dialog_content = "เราเพิ่งมาถึง แต่ก็รู้แล้วล่ะว่าเกิดอะไรขึ้น",
  ui_story_5014_50140902_20_dialog_content = "หลังจากตรวจร่างกายคร่าว ๆ ฉันว่าเธอไม่เป็นไรแล้ว",
  ui_story_5014_50140902_21_dialog_content = "หวัดดี~ สบายดีป่าว?",
  ui_story_5014_50140902_22_dialog_content = "เมื่อกี้โทษทีนะ ฉันไม่ได้ตั้งใจจะทำให้นายตกใจเลย",
  ui_story_5014_50140902_23_dialog_content = "ฉันไม่เป็นไร... แต่แรงระเบิดนั่น... มันมาโดยที่ไม่ทันตั้งตัว...",
  ui_story_5014_50140902_24_dialog_content = "ก็จริง ฉันผิดเองแหละ",
  ui_story_5014_50140902_25_dialog_content = "ขอโอกาสฉันทำความรู้จักกับทุกคนอีกรอบก็แล้วกันนะ",
  ui_story_5014_50140902_26_dialog_content = "พี่สาวคนนี้คือนักสำรวจชื่อดัง เชอวานแห่งอิลลูมินา...",
  ui_story_5014_50140902_27_dialog_content = "และนี่ก็คือสุดยอดนักผจญภัย ฟลอรีนแห่งลูโมโพลิส",
  ui_story_5014_50140902_28_dialog_content = "เธอรู้จักทุกคนเลยเหรอเนี่ย?",
  ui_story_5014_50140902_29_dialog_content = "ก็พวกเธอเป็นคนดังในวงการนักผจญภัยนี่นา",
  ui_story_5014_50140902_30_dialog_content = "ว่าแต่นายเป็นใครกันแน่",
  ui_story_5014_50140902_31_dialog_content = "ฉันจำไม่ได้ว่ามีนักผจญภัยที่ชอบแต่งหญิงนะ...",
  ui_story_5014_50140902_32_dialog_content = "พอได้แล้ว หยุดเลยนะ ฉันไม่มีทางเลือกนี่นา!",
  ui_story_5014_50140902_33_dialog_content = "(เกือบจะลืมเรื่องนี้ได้แล้วนะเนี่ย... ทำไมต้องมาตอกย้ำอยู่เรื่อยเลย ให้ตายสิ...)",
  ui_story_5014_50140902_34_dialog_content = "ฉันชื่อ PlayerName เป็นเคเลสไทต์ พวกเธอนักผจญภัยคงจะเคย...",
  ui_story_5014_50140902_35_dialog_content = "นายคือเคเลสไทต์... ที่ลูกพี่ซินซาพูดถึงบ่อย ๆ เหรอเนี่ย...",
  ui_story_5014_50140902_36_dialog_content = "พี่รูบี้ พอเถอะน่า เราไม่มีเวลาแล้วนะ!",
  ui_story_5014_50140902_37_dialog_content = "คุณเชอวาน พูดต่อเถอะค่ะ",
  ui_story_5014_50140902_38_dialog_content = "พวกเธอเป็นใคร มาทำอะไรที่นี่?",
  ui_story_5014_50140902_39_dialog_content = "ฉันชื่อรูบี้ ส่วนนี่น้องสาวของฉัน รูจ",
  ui_story_5014_50140902_40_dialog_content = "พวกเราเป็นนักผจญภัยฝีมือดีจากเรดีเซล เวรนช์ เป็นเกียรติอย่างยิ่งที่ได้พบ เจ้าหญิงคาร์ลีน",
  ui_story_5014_50140902_41_dialog_content = "ว่าแต่เธอมาหาสมบัติหรือมาจับโจรกันล่ะ?",
  ui_story_5014_50140902_42_dialog_content = "ไม่ใช่ทั้งคู่นั่นแหละ",
  ui_story_5014_50140902_43_dialog_content = "พวกเธอเข้ามาในนี้ได้ยังไง? รู้มั้ยว่าทางออกอยู่ที่ไหน?",
  ui_story_5014_50140902_44_dialog_content = "เราร่วงตุ๊บลงมาจากข้างบนน่ะ เอาจริง ๆ ตอนนี้ยังงงอยู่เลยว่าที่นี่คือที่ไหน~",
  ui_story_5014_50140902_45_dialog_content = "พอเถอะ! ให้ฉันพูดดีกว่า!",
  ui_story_5014_50140902_46_dialog_content = "เราได้รับสัญญาณประหลาดก็เลยตามรอยมาจนเจอหลุมขนาดใหญ่",
  ui_story_5014_50140902_47_dialog_content = "หลุมนั่นเป็นอุโมงค์ที่มีทางลงมาข้างล่าง...",
  ui_story_5014_50140902_48_dialog_content = "พวกเราเจอแผ่นดินไหว ก็เลยตกลงมา",
  ui_story_5014_50140902_49_dialog_content = "ฉันบอกแล้วใช่มั้ยว่าเราควรอยู่ให้ห่างจากอุโมงค์นั่น แล้วพี่ก็ไม่ฟังเลย",
  ui_story_5014_50140902_50_dialog_content = "โทษทีจ้า~ โทษที~",
  ui_story_5014_50140902_51_dialog_content = "งั้นเหรอ? แล้วอุโมงค์นั่นอยู่ไหน?",
  ui_story_5014_50140902_52_dialog_content = "เราไถลเข้าไปในถ้ำใต้ดินอีกทาง",
  ui_story_5014_50140902_53_dialog_content = "แล้วเราก็ย้อนรอยกลับทางเดิมไม่ได้ เลยต้องเดินเข้าถ้ำไปเรื่อย ๆ...",
  ui_story_5014_50140902_54_dialog_content = "จากนั้นเราก็ตามปล่องทางเข้าจนมาเจอเมือง",
  ui_story_5014_50140902_55_dialog_content = "เราไม่รู้เลยว่ามีเมืองใต้ขนาดใหญ่ที่เต็มไปด้วยสมบัติมากมายขนาดนี้",
  ui_story_5014_50140902_56_dialog_content = "เรานี่โชคดีเป็นบ้าเลย~",
  ui_story_5014_50140902_57_dialog_content = "พี่รูบี้ ตื่นก่อน ตอนนี้เรายังหาทางออกไม่ได้เลยนะ!",
  ui_story_5014_50140902_58_dialog_content = "ทำไมล่ะ? รู้ได้ไงว่าเราจะออกไปไม่ได้?",
  ui_story_5014_50140902_59_dialog_content = "พวกเขาเพิ่งถามเราว่าทางออกอยู่ที่ไหน ก็แสดงว่าพวกเราทุกคนติดอยู่ในนี้ชัด ๆ เลย!",
  ui_story_5014_50140902_60_dialog_content = "โอ้วว แย่จังแฮะ",
  ui_story_5014_50140902_61_dialog_content = "เฮ้ ทำไมทุกคนนิ่งไปแบบนั้นล่ะ?",
  ui_story_5014_50140902_62_dialog_content = "ฉัน... ฉันไม่รู้เลยนะเนี่ย ว่าเรายังติดอยู่ใต้ดิน...",
  ui_story_5014_50140902_63_dialog_content = "ท้องฟ้านั่นไม่ใช่ของจริงเหรอ?",
  ui_story_5014_50140902_64_dialog_content = "ก็ไม่ใช่น่ะสิ แต่ถือว่าทำเหมือนมากเลยนะ",
  ui_story_5014_50140902_65_dialog_content = "อยากจะลองเคาะดูเหมือนกัน ว่ามันทำมาจากอะไร",
  ui_story_5014_50140902_66_dialog_content = "เราร่วงลงมาตอนที่ข้างบนเป็นเวลากลางคืน ไม่งั้นก็คงจะไม่รู้ตัวเหมือนกัน",
  ui_story_5014_50140902_67_dialog_content = "เพราะที่นี่มีมิติเวลาที่ผิดปกติ เราก็เลยไม่รู้ตัวว่าตัวเองอยู่ใต้ดิน...",
  ui_story_5014_50140902_68_dialog_content = "แถมหุ่นนั่นก็เอาแต่ขวางไม่ให้เราสำรวจเมือง",
  ui_story_5014_50140902_69_dialog_content = "เธอลงมาที่นี่ได้ยังไง?",
  ui_story_5014_50140902_70_dialog_content = "ก็เหมือนพวกเธอนั่นแหละ",
  ui_story_5014_50140902_71_dialog_content = "แผ่นดินไหวบ่อยครั้งได้ทำลายสิ่งอำนวยความสะดวกบางส่วนของเมืองใต้นี้",
  ui_story_5014_50140902_72_dialog_content = "รวมถึงทางที่เราเข้ามาด้วย",
  ui_story_5014_50140902_73_dialog_content = "ฉันสงสัยว่าบัตเลอร์จงใจเจาะผิวดินเพื่อล่อพวกเราเข้ามารึเปล่า",
