  ui_story_5014_50140902_75_dialog_content = "ไม่น่าจะเป็นแบบนั้นนะ...",
  ui_story_5014_50140902_76_dialog_content = "บัตเลอร์นั่นถูกตั้งโปรแกรมให้ปกป้องสองพี่น้อง มันคงไม่อยากให้เด็กพวกนั้นติดต่อกับคนภายนอกหรอก",
  ui_story_5014_50140902_77_dialog_content = "บัตเลอร์อะไรนะ? พี่น้อง? คุณพูดเรื่องอะไรน่ะ?",
  ui_story_5014_50140902_78_dialog_content = "มนุษย์โบราณสร้างเมืองใต้นี้เพื่อหนีจากสงครามและภัยพิบัติ",
  ui_story_5014_50140902_79_dialog_content = "แต่ที่นี่น่ะ ไม่เหมือนเมืองของอิลลูมินาเลยแม้แต่นิดเดียว",
  ui_story_5014_50140902_80_dialog_content = "ขวา. เมืองใต้ของ Illumina ล้วนสร้างขึ้นด้วยสิ่งอำนวยความสะดวกทางทหารที่หลากหลาย",
  ui_story_5014_50140902_81_dialog_content = "ส่วนเมืองนี้มีแต่สิ่งอำนวยความสะดวกอัตโนมัติเพื่อการใช้ชีวิตและการผลิต แล้วก็มีหุ่นยนต์บังคับใช้กฎหมายจำนวนหนึ่ง",
