  ui_story_5014_50140902_89_dialog_content = "เจ้าบัตเลอร์นั่นต้องรู้วิธีออกไปแน่ ๆ แต่มันกลัวว่าเราอาจจะออกไปบอกคนอื่นและทำให้เมืองนี้ถูกค้นพบ",
