  ui_story_5014_50141002_36_dialog_content = "<color=#e8d9bb>โปรด... ถอยไป</color>",
  ui_story_5014_50141002_37_dialog_content = "<color=#e8d9bb>พลังต่อสู้... ไม่เพียงพอ... กรุณาหนีไป</color>",
  ui_story_5014_50141002_38_dialog_content = "บัตเลอร์ นายบอกว่าแก้ไขได้ไม่ใช่เหรอ! นายบอกว่า...",
  ui_story_5014_50141002_39_dialog_content = "<color=#e8d9bb>อิคลิพไซท์... มากเกินไป... โปรดหนีไปเถอะ</color>",
  ui_story_5014_50141002_40_dialog_content = "กรร! กรร!",
  ui_story_5014_50141002_41_dialog_content = "เกรเทล ไปซ่อนในที่ปลอดภัยก่อนนะ ฉันจะช่วยบัตเลอร์จัดการผู้บุกรุกเอง...",
  ui_story_5014_50141002_42_dialog_content = "ไม่เอาแล้ว... พอกันทีกับการหลบ ๆ ซ่อน ๆ...",
  ui_story_5014_50141002_43_dialog_content = "อิคลิพไซท์เยอะแบบนี้... บัตเลอร์จะต้องตาย... พี่ก็จะต้องตาย...",
  ui_story_5014_50141002_44_dialog_content = "เหมือนพ่อกับแม่...",
  ui_story_5014_50141002_45_dialog_content = "ฉันไม่อยากให้พี่ตาย... ไม่เอาแบบนี้...",
  ui_story_5014_50141002_46_dialog_content = "เกรเทล? ตั้งสติหน่อย...",
  ui_story_5014_50141002_47_dialog_content = "ไม่!",
  ui_story_5014_50141002_48_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5014_50141002_49_dialog_content = "<color=#e8d9bb>ฉัวะ...</color>",
  ui_story_5014_50141002_50_dialog_content = "หืม... อะไรน่ะ?",
  ui_story_5014_50141002_51_dialog_content = "จู่ ๆ ก็มีกระแสพลังลูมินาที่รุนแรงมากเกิดขึ้นในร่างกายของเธอ",
  ui_story_5014_50141002_52_dialog_content = "อิคลิพไซท์ทุกตัวโดนกำจัดไม่เหลือ",
  ui_story_5014_50141002_53_dialog_content = "เกรเทล ตื่นสิ! ไม่เอานะ อย่าทำให้พี่ใจคอไม่ดีแบบนี้สิ! เกรเทล!",
  ui_story_5014_50141002_54_dialog_content = "อา... พี่... ฉันไม่เป็นไร...",
  ui_story_5014_50141002_55_dialog_content = "ขอบคุณสวรรค์... เธอปลอดภัย...",
  ui_story_5014_50141002_56_dialog_content = "พี่จะพาเธอไปรักษานะ แข็งใจไว้...",
  ui_story_5014_50141002_57_dialog_content = "บัตเลอร์ มาช่วยฉันที!",
  ui_story_5014_50141002_58_dialog_content = "<color=#e8d9bb>ระบบรักษาเร่งด่วน... เปิดใช้งาน ตามผมมาเลย</color>",
  ui_story_5014_50141002_59_dialog_content = "วาเลนเซีย เราขอไปด้วยนะ...",
  ui_story_5014_50141002_60_dialog_content = "หยุดตรงนั้นเลยนะ!",
  ui_story_5014_50141002_61_dialog_content = "อยู่ตรงนั้นแหละ ไม่ต้องไปไหนทั้งนั้น",
  ui_story_5014_50141002_62_dialog_content = "วาเลนเซีย เราแค่อยากจะช่วยเธอนะ...",
  ui_story_5014_50141002_63_dialog_content = "ฉันไม่ต้องการ!",
  ui_story_5014_50141002_64_dialog_content = "น้องสาวของฉันไม่อยากเจอพวกคุณ",
  ui_story_5014_50141101_1_dialog_content = "... เป็นฝีมือเกรเทลเหรอเนี่ย?",
  ui_story_5014_50141101_2_dialog_content = "ใช่ อารมณ์ที่เอ่อล้นสุดขีดทำให้ลูมินาของเธอระเบิดพลังออกมา",
  ui_story_5014_50141101_3_dialog_content = "ไม่นึกเลยว่าเด็กตัวแค่นั้นจะมีพลังมากมายขนาดนี้",
  ui_story_5014_50141101_4_dialog_content = "ประธาน ฉันรู้สึกไม่ดีเลย...",
  ui_story_5014_50141101_5_dialog_content = "อื้อ เธอคงจะอึดอัดมากสินะ",
  ui_story_5014_50141101_6_dialog_content = "มีแต่เรื่องเกินความคาดหมายมากมาย ที่จริงตอนนี้เราควบคุมอะไรไม่ได้เลยด้วยซ้ำ",
  ui_story_5014_50141101_7_dialog_content = "เราต้องรีบหาทางออกและติดต่อคุณเฮดี้โดยด่วน",
  ui_story_5014_50141101_8_dialog_content = "สิ่งที่เธอจะทำ... เด็กสองคนนั้นจะไม่เป็นอันตรายใช่มั้ย...",
  ui_story_5014_50141101_9_dialog_content = "ไม่หรอกค่ะ ยังไงพวกเธอก็เป็นลูกหลานของชาวลูโมโพลิส",
  ui_story_5014_50141101_10_dialog_content = "งั้นเอาไงต่อดีล่ะ? วาเลนเซียสั่งให้เราอยู่ตรงนี้",
  ui_story_5014_50141101_11_dialog_content = "เราต้องหาห้องของซีมัสให้เจอ",
  ui_story_5014_50141101_12_dialog_content = "จากที่ได้คุยกับบัตเลอร์ไปแล้วนิดหน่อย ฉันว่าเราต้องรีบหาข้อมูลวิจัยของซีมัสให้เจอโดยด่วนที่สุด",
  ui_story_5014_50141101_13_dialog_content = "ฉันจำพิกัดได้ ตามฉันมา",
  ui_story_5014_50141101_14_dialog_content = "<color=#e8d9bb>บี๊ป... บี๊ป...</color>",
  ui_story_5014_50141101_15_dialog_content = "เสียงอะไรน่ะ?",
  ui_story_5014_50141101_16_dialog_content = "ข้อความจากรูบี้...",
  ui_story_5014_50141101_17_dialog_content = "เฮ้! ได้ยินพวกเรามั้ย?",
  ui_story_5014_50141101_18_dialog_content = "ช่วยพวกเราด้วย!",
  ui_story_5014_50141101_19_dialog_content = "ไม่งั้นรูจโกรธฉันตายเลย!",
  ui_story_5014_50141101_20_dialog_content = "โอ๊ย... แสบแก้วหูจัง!",
  ui_story_5014_50141101_21_dialog_content = "พวกเธอตกอยู่ในอันตราย... เราควรไปช่วยพวกเธอดีมั้ย?",
  ui_story_5014_50141101_22_dialog_content = "ถึงพวกนั้นจะเป็นคนของเรดีเซล เวรนช์ แต่เธอก็ไม่เห็นจะต้องใจจืดใจดำเลยนี่นา",
  ui_story_5014_50141101_23_dialog_content = "งั้นก็เร็วเข้าเถอะ อย่ามัวเสียเวลาเลย",
  ui_story_5014_50141101_24_dialog_content = "พวกนั้นอยู่ไม่ไกลจากเป้าหมายของเราเท่าไหร่",
  ui_story_5014_50141101_25_dialog_content = "ที่นั่นอาจจะมีหุ่นยนต์หรือไม่ก็อิคลิพไซท์อยู่ด้วย",
  ui_story_5014_50141101_26_dialog_content = "เพราะเอกสารที่ซีมัสทิ้งไว้ให้น่ะเหรอ?",
  ui_story_5014_50141101_27_dialog_content = "ใช่ บัตเลอร์อาจจะรู้แล้วว่าเรากำลังตามหาเอกสารอยู่ เราต้องรีบแล้ว",
  ui_story_5014_50141101_28_dialog_content = "ก็ได้ เราจะนำให้เอง",
  ui_story_5014_50141101_29_dialog_content = "เอริก้า เพิ่มความเร็วกับพลังทีสิ เราจะต้องรีบไปให้ถึง แล้วก็ต้องเคลียร์ทางด้วย!",
  ui_story_5014_50141101_30_dialog_content = "ค่ะ ประธาน",
  ui_story_5014_50141101_31_dialog_content = "<color=#e8d9bb>เปรี๊ยะ! เปรี้ยง!</color>",
  ui_story_5014_50141101_32_dialog_content = "พี่รูบี้ พวกนั้นมาแล้ว!",
  ui_story_5014_50141101_33_dialog_content = "รูบี้ รูจ! ไม่เป็นไรใช่มั้ย?",
  ui_story_5014_50141101_34_dialog_content = "ชี่... เอี๊ยด... เปรี๊ยะ... เอี๊ยด...",
  ui_story_5014_50141101_35_dialog_content = "ขอบคุณพระเจ้า! นึกว่าคุณจะไม่มาซะแล้ว",
  ui_story_5014_50141101_36_dialog_content = "เกิดอะไรขึ้น? พวกหุ่นโจมตีเธอเหรอ? พวกมันพูดอะไรบ้างรึเปล่า?",
  ui_story_5014_50141101_37_dialog_content = "นั่นสิ? เรายังไม่ได้ทำอะไรเลยด้วยซ้ำ",
  ui_story_5014_50141101_38_dialog_content = "คำเตือน! โปรดนำทรัพย์สินกลับมาคืนด้วย! คำเตือน! โปรดนำทรัพย์สินกลับมาคืนด้วย!",
  ui_story_5014_50141101_39_dialog_content = "พี่รูบี้... ฉันบอกแล้วไม่ใช่หรือไง ว่าเราฉกของต่อหน้าพวกมันไม่ได้!",
  ui_story_5014_50141101_40_dialog_content = "... เธอขโมยอะไรมาน่ะ?",
  ui_story_5014_50141101_41_dialog_content = "ให้ตายสิ! ก็แค่ของเก่าเท่านั้นเอง! มันไม่มีเจ้าของแล้วนี่นา!",
  ui_story_5014_50141101_42_dialog_content = "แล้วมันไม่ใช่ธุระของเจ้าเศษเหล็กพวกนี้ด้วย จะมีปัญหาอะไรกันนักกันหนา?",
  ui_story_5014_50141101_43_dialog_content = "เริ่มโปรแกรมจับกุม!",
  ui_story_5014_50141101_44_dialog_content = "ก๊าาาซ!",
  ui_story_5014_50141101_45_dialog_content = "อิคลิพไซท์บุกมาใกล้แล้ว!",
  ui_story_5014_50141101_46_dialog_content = "ต้องรับศึกสองฝั่งเลยเหรอเนี่ย ระวังตัวด้วยล่ะ...",
  ui_story_5014_50141102_1_dialog_content = "หนึ่งตัว สองตัว!",
  ui_story_5014_50141102_2_dialog_content = "เปรี๊ยะ... อา...",
  ui_story_5014_50141102_3_dialog_content = "สาม สี่...",
  ui_story_5014_50141102_4_dialog_content = "รูบี้ นี่ไม่ใช่เวลามาสนุกกับการต่อสู้นะ ศัตรูแห่กันมาเพิ่มอีกแล้ว",
  ui_story_5014_50141102_5_dialog_content = "เราต้องหาเอกสารที่ซีมัสทิ้งเอาไว้ให้เจอ",
  ui_story_5014_50141102_6_dialog_content = "คนที่คุณพูดถึงน่ะเหรอ? แล้วเอกสารนั่นอยู่ไหนล่ะ?",
  ui_story_5014_50141102_7_dialog_content = "ในเขตที่อยู่อาศัยน่ะสิ... ตามฉันมา ฟลอรีนกับกลุ่มของเธอล่วงหน้าไปเคลียร์ทางให้แล้ว",
  ui_story_5014_50141102_8_dialog_content = "โอ้? เรามีหน้าที่ระวังหลังให้พวกนั้นสินะ?",
  ui_story_5014_50141102_9_dialog_content = "คุณเชอวาน ห้องของซีมัสอยู่ในอาคารข้างหน้านี่เอง เราเจอแล้ว!",
  ui_story_5014_50141102_10_dialog_content = "ยอดมาก ตอนนี้เราพอจะสลัดพวกหุ่นพ้นแล้ว เร็วเข้าเถอะ",
  ui_story_5014_50141102_11_dialog_content = "ฟู่... ในที่สุด... ก็ถึงจนได้",
  ui_story_5014_50141102_12_dialog_content = "ตึกนี่แข็งแรงพอรึเปล่าน่ะ?",
  ui_story_5014_50141102_13_dialog_content = "ถ้าเราต้องสู้กับศัตรู มันจะพังลงมามั้ย?",
  ui_story_5014_50141102_14_dialog_content = "ก็เป็นไปได้นะ บ้านเรือนในเขตที่อยู่อาศัยมันก็เก่าเต็มทนแล้ว",
  ui_story_5014_50141102_15_dialog_content = "ถ้าต้องสู้จริง ๆ ก็ช่วยยั้งมือด้วยล่ะ",
  ui_story_5014_50141102_16_dialog_content = "สไตล์การต่อสู้ของเธอมันเถื่อนใช้ได้เลย",
  ui_story_5014_50141102_17_dialog_content = "เข้าใจแล้ว ฉันจะเชื่อคุณก็แล้วกัน จากนี้ไปพวกเราคือ \"ทีมนักผจญภัย\"",
  ui_story_5014_50141102_18_dialog_content = "มาถึงจนได้... นี่สินะ ห้องของซีมัส",
  ui_story_5014_50141102_19_dialog_content = "ห้องนี้...",
  ui_story_5014_50141102_20_dialog_content = "ไม่มีคนอยู่มาสักพักแล้วนะเนี่ย",
  ui_story_5014_50141102_21_dialog_content = "มีอะไรเหรอ? ทุกห้องมันก็ว่างแบบนี้นั่นแหละ",
  ui_story_5014_50141102_22_dialog_content = "ดูสิ... เสื้อผ้ากับหนังสือพวกนี้ไม่มีฝุ่นจับเลย",
  ui_story_5014_50141102_23_dialog_content = "เด็กพวกนั้น... ดูแลทำความสะอาดอยู่ตลอด",
  ui_story_5014_50141102_24_dialog_content = "ว้าว... มีเดรสผู้หญิงอยู่ด้วย จะขายได้เท่าไหร่นะ",
  ui_story_5014_50141102_25_dialog_content = "พี่รูบี้ อย่านะ ถ้าเด็กสองคนนั้นรู้เราโดนเชือดแน่!",
  ui_story_5014_50141102_26_dialog_content = "แค่ล้อเล่นน่า... นี่คงจะเป็นของดูต่างหน้าของสามีภรรยาซีมัสใช่มะ?",
  ui_story_5014_50141102_27_dialog_content = "ฉันไม่ขโมยอะไรต่อหน้าให้นายเห็นหรอก",
  ui_story_5014_50141102_28_dialog_content = "เธอ...",
  ui_story_5014_50141102_29_dialog_content = "แค่มุกตลกน่า อย่าจริงจังกับชีวิตนักสิจ๊ะ",
  ui_story_5014_50141102_30_dialog_content = "พวกเราเป็นนักผจญภัยมืออาชีพ และเราก็ทำตามหลักจรรยาบรรณอย่างเคร่งครัด",
  ui_story_5014_50141102_31_dialog_content = "เราต้องหาข้อมูลวิจัยของคุณซีมัสให้เจอ",
  ui_story_5014_50141102_32_dialog_content = "มีให้เลือกเยอะแยะไปหมดเลย... ไวซ์ มาช่วยฉันคัดข้อมูลสำคัญทีสิ",
  ui_story_5014_50141102_33_dialog_content = "ได้ค่ะ!",
  ui_story_5014_50141102_34_dialog_content = "คุณเชอวานคะ ทั้งหมดนี่คืองานของคุณซีมัสเหรอ?",
  ui_story_5014_50141102_35_dialog_content = "ใช่ นี่เป็นลายมือของซีมัส",
  ui_story_5014_50141102_36_dialog_content = "ทุกอย่างยังเหมือนในความทรงจำไม่มีผิด...",
  ui_story_5014_50141102_37_dialog_content = "คุณเชอวาน มือของคุณ... สั่นเหรอ?",
  ui_story_5014_50141102_38_dialog_content = "อืมม... ฉันนึกว่าจะไม่ได้เห็นงานวิจัยล้ำค่าพวกนี้อีกแล้วน่ะสิ...",
  ui_story_5014_50141102_39_dialog_content = "ฉันแค่ตื่นเต้นน่ะ... ช่างเถอะ มาคัดเอกสารกันดีกว่า",
  ui_story_5014_50141102_40_dialog_content = "คุณเชอวาน มีแต่รหัสลับเต็มไปหมด... ฉันอ่านไม่รู้เรื่องเลย",
  ui_story_5014_50141102_41_dialog_content = "ไม่เป็นไร ใช้กุญแจทั่วไปถอดรหัสก่อนก็ได้ เดี๋ยวอันยาก ๆ ฉันค่อยจัดการทีหลัง",
  ui_story_5014_50141102_42_dialog_content = "ค่ะ!",
  ui_story_5014_50141102_43_dialog_content = "คาร์ลีน ฉันว่าพวกนั้นคงใช้เวลาเก็บข้อมูลสักพักเลย",
  ui_story_5014_50141102_44_dialog_content = "ถ้าอิคลิพไซท์กับหุ่นยนต์ตามมาเจอล่ะก็...",
  ui_story_5014_50141102_45_dialog_content = "เข้าใจแล้ว เดี๋ยวฉันเฝ้าประตูให้ จะไม่มีใครหน้าไหนเข้ามาได้เป็นอันขาด",
  ui_story_5014_50141102_46_dialog_content = "ประธานคะ ดูนี่สิ",
  ui_story_5014_50141102_47_dialog_content = "มีอะไรเหรอ เอริก้า?",
  ui_story_5014_50141102_48_dialog_content = "ฉันเจอไดอารี่เพิ่มล่ะ",
  ui_story_5014_50141102_49_dialog_content = "แถมยังมีตราประทับทองคำด้วย...",
  ui_story_5014_50141102_50_dialog_content = "ในดินแดนอันมืดมิดของพวกนอกรีต ยังมีร่องรอยของเทพแห่งแสงสว่างอยู่หรือนี่?",
  ui_story_5014_50141102_51_dialog_content = "นี่เป็นเครื่องหมายในสไตล์ของลูโมโพลิส... คงเป็นของนิมบัสสินะ",
  ui_story_5014_50141102_52_dialog_content = "เราลองอ่านดูดีมั้ยคะ ประธาน?",
  ui_story_5014_50141102_53_dialog_content = "ก็ดีนะ... ฉันก็อยากรู้เหมือนกันว่าชนชั้นสูงของลูโมโพลิสมาอยู่ที่นี่ได้ยังไง",
  ui_story_5014_50141102_54_dialog_content = "พวกเธอจะอ่านไดอารี่ของนิมบัสเหรอ?",
  ui_story_5014_50141102_55_dialog_content = "นี่! อย่าเข้ามาใกล้แบบนั้นสิ ฉันตกใจนะ...",
  ui_story_5014_50141102_56_dialog_content = "โทษที ฉันก็อยากอ่านเหมือนกันน่ะ",
  ui_story_5014_50141102_57_dialog_content = "ไม่ต้องห่วง ฉันว่าประธานไม่น่าจะเข้าใจเท่าไหร่",
  ui_story_5014_50141102_58_dialog_content = "เอ่อ? ตัวหนังสือยึกยือนี่มันอะไรน่ะ?",
  ui_story_5014_50141102_59_dialog_content = "มันคือชวเลขที่ชนชั้นสูงใช้กันน่ะ ฉันก็อ่านออกแค่บางตัว",
  ui_story_5014_50141102_60_dialog_content = "\"ชวเลข\" งั้นเหรอ?",
  ui_story_5014_50141102_61_dialog_content = "มันคือการเขียนข้อความด้วยตัวอักษรพิเศษที่เข้าใจกันเฉพาะกลุ่มน่ะ",
  ui_story_5014_50141102_62_dialog_content = "เป็นคู่รักที่ชอบการเข้ารหัสจังเลยแฮะ",
  ui_story_5014_50141102_63_dialog_content = "นิมบัสคงมีเรื่องบางอย่างที่อยากบอกลูโมโพลิส...",
  ui_story_5014_50141102_64_dialog_content = "แล้วซีมัสก็คงมีอะไรบางอย่างที่อยากบอกอิลลูมินาสินะ?",
  ui_story_5014_50141102_65_dialog_content = "นี่มันเหมือนความสัมพันธ์ระหว่างลูโมโพลิสกับอิลลูมินาเลย ทั้งคู่ต่างก็ปกปิดความลับของตัวเอง",
  ui_story_5014_50141102_66_dialog_content = "แต่พวกเขาเป็นคู่รักกันนะ?",
  ui_story_5014_50141102_67_dialog_content = "อยู่ด้วยกันแบบนี้ไม่อึดอัดแย่เหรอ?",
  ui_story_5014_50141102_68_dialog_content = "เงียบเถอะน่า พี่น้องเรดีเซล... ฉันอ่านบันทึกพวกนี้แล้ว ซีมัสน่ะ รักภรรยาของเขามากเลยนะ",
  ui_story_5014_50141102_69_dialog_content = "ทั้งคู่ให้เกียรติซึ่งกันและกันมาก เลยเปิดโอกาสให้ต่างฝ่ายได้มีอิสระ",
  ui_story_5014_50141102_70_dialog_content = "พวกเขารู้เรื่องข้อมูลเข้ารหัสของอีกฝ่าย... นิมบัสเขียนเรื่องนี้ไว้ในไดอารี่เหมือนกัน",
  ui_story_5014_50141102_71_dialog_content = "<color=#e8d9bb>เอี๊ยด... ครืด</color>",
  ui_story_5014_50141102_72_dialog_content = "มีใครมาน่ะ?",
  ui_story_5014_50141102_73_dialog_content = "หุ่นยนต์เหรอ หรือว่าอิคลิพไซท์?",
  ui_story_5014_50141102_74_dialog_content = "เป็นหุ่นยนต์ครับ... แต่...",
  ui_story_5014_50141102_75_dialog_content = "มันไม่โจมตีเราแฮะ?",
  ui_story_5014_50141102_76_dialog_content = "บี๊บ",
  ui_story_5014_50141102_77_dialog_content = "หมาหุ่นยนต์... คงเป็นสัตว์เลี้ยงของคุณซีมัสล่ะมั้ง?",
  ui_story_5014_50141102_78_dialog_content = "ดูท่าทางไม่น่าจะอันตรายนะ",
  ui_story_5014_50141102_79_dialog_content = "ถ้าไม่มีอะไรก็ปล่อยมันไปเถอะ... เรามาสนใจเรื่องเก็บข้อมูลดีกว่า",
  ui_story_5014_50141102_80_dialog_content = "นั่นสินะ",
  ui_story_5014_50141102_81_dialog_content = "อาจารย์เชอวานคะ ช่วยอ่านบันทึกของฉัน...",
  ui_story_5014_50141102_82_dialog_content = "บี๊ป บี๊ป บี๊ป บี๊ป...",
  ui_story_5014_50141102_83_dialog_content = "เหมือนเจ้าหมาน้อยนี่จะอยากออกไปนะ",
  ui_story_5014_50141102_84_dialog_content = "รูจ ในเมื่อตอนนี้เราไม่มีอะไรทำ... ขอฉันเล่นกับมันได้มั้ย?",
  ui_story_5014_50141102_85_dialog_content = "เฮ้อ... ก็ได้ แต่อย่าไปไหนไกลล่ะ",
  ui_story_5014_50141102_86_dialog_content = "ได้เลย!",
  ui_story_5014_50141102_87_dialog_content = "เจ้าหมานี่ตลกดีแฮะ...",
  ui_story_5014_50141102_88_dialog_content = "<color=#e8d9bb>ออโรเรียน... บุกรุก... ห้องของซีมัส...</color>",
  ui_story_5014_50141102_89_dialog_content = "ฉันเห็นแล้ว... หนอย",
  ui_story_5014_50141102_90_dialog_content = "<color=#e8d9bb>กรุณา... ออกคำสั่ง...</color>",
  ui_story_5014_50141102_91_dialog_content = "ส่งหุ่นยนต์ทั้งหมดที่มีไปจัดการ เดี๋ยวนี้เลย!",
  ui_story_5014_50141102_92_dialog_content = "<color=#e8d9bb>กำลังรวบรวม... กำลังส่งไปยัง... เขตที่อยู่อาศัย</color>",
  ui_story_5014_50141102_93_dialog_content = "พี่คะ... พี่จะไปแล้วเหรอ?",
  ui_story_5014_50141102_94_dialog_content = "อืม ฉันต้องหยุดพวกนั้น... ไม่ให้ทำลายห้องของพ่อกับแม่",
  ui_story_5014_50141102_95_dialog_content = "งั้นฉันจะไปด้วย!",
  ui_story_5014_50141102_96_dialog_content = "อย่าเลย... อยู่ตรวจร่างกายที่นี่ก่อนเถอะ",
  ui_story_5014_50141102_97_dialog_content = "พี่ไปไม่นานหรอก แล้วพี่จะรีบกลับมานะ",
  ui_story_5014_50141102_98_dialog_content = "แต่ พี่คะ ลำพังพี่ตัวคนเดียวเอาชนะพวกเขาไม่ได้หรอก",
  ui_story_5014_50141102_99_dialog_content = "หนูเพิ่งได้พลังมา หนูมั่นใจว่า...",
  ui_story_5014_50141102_100_dialog_content = "เธอน่ะใจร้อนไปแล้ว ดูแลตัวเองก่อนเถอะ",
  ui_story_5014_50141102_101_dialog_content = "ที่ผ่านมาพี่ก็แค่ไม่อยากสู้กับพวกเขา",
  ui_story_5014_50141102_102_dialog_content = "แต่ตอนนี้... พี่ีรู้แล้วว่าจะต้องทำอะไร",
  ui_story_5014_50141102_103_dialog_content = "ให้หนูไปด้วยเถอะนะ... หนูไม่อยากรอที่นี่คนเดียว",
  ui_story_5014_50141102_104_dialog_content = "ขอร้องล่ะ พี่... หนูไม่อยากอยู่คนเดียว มันน่ากลัวมากเลย",
  ui_story_5014_50141102_105_dialog_content = "เฮ่อ... งั้นก็สัญญากับพี่ก่อนว่าอย่าฝืนตัวเอง แล้วก็อย่าใช้พลังนั่นมากเกินไป",
  ui_story_5014_50141102_106_dialog_content = "สัญญา!",
  ui_story_5014_50141201_1_dialog_content = "ทุกคน... หุ่นยนต์มาแล้ว!",
  ui_story_5014_50141201_2_dialog_content = "โอ้ว? ได้เวลาโชว์ฝีมือแล้วสิ",
  ui_story_5014_50141201_3_dialog_content = "ถอดรหัสกันต่อได้เลยนะ เราจะป้องกันประตูให้เอง",
  ui_story_5014_50141201_4_dialog_content = "ฉันกลัวว่าประตูนี่จะต้านไม่ไหวแล้วน่ะสิ...",
  ui_story_5014_50141201_5_dialog_content = "ทำไมพูดยังงั้นล่ะ?",
  ui_story_5014_50141201_6_dialog_content = "เพราะวาเลนเซียกับเกรเทลมาด้วยน่ะสิ...",
  ui_story_5014_50141201_7_dialog_content = "เราไม่มีสิทธิ์ห้ามเธอ... ไม่ให้เข้าห้องพ่อของตัวเอง",
  ui_story_5014_50141201_8_dialog_content = "ฉันจะไปคุยกับวาเลนเซียเอง",
  ui_story_5014_50141201_9_dialog_content = "พวกหัวขโมย!",
  ui_story_5014_50141201_10_dialog_content = "วาเลนเซีย ฟังฉันก่อน...",
  ui_story_5014_50141201_11_dialog_content = "ออกไปจากห้องพ่อแม่ของฉันเลยนะ!",
  ui_story_5014_50141201_12_dialog_content = "ขึ้นเสียงแบบนั้นมันอะไรกันน่ะ?!",
  ui_story_5014_50141201_13_dialog_content = "เราก็แค่จัดห้องให้เธอนิดหน่อยเอง! ไม่ได้มาขโมยอะไรซะหน่อย!",
  ui_story_5014_50141201_14_dialog_content = "ข้อมูลนั่นเป็นของพ่อแม่ฉัน! กล้าดียังไงถึงมาสอดรู้สอดเห็นเรื่องคนอื่น!!",
  ui_story_5014_50141201_15_dialog_content = "วาเลนเซีย ฉันมาที่นี่ก็เพราะประกาศที่ซีมัสทิ้งไว้",
  ui_story_5014_50141201_16_dialog_content = "นี่เป็นสิ่งที่พ่อของเธอต้องการ...",
  ui_story_5014_50141201_17_dialog_content = "ประกาศบ้าอะไรกัน? ฉันไม่เห็นรู้เรื่องเลย",
  ui_story_5014_50141201_18_dialog_content = "มันมาจากเครื่องสื่อสารของพ่อเธอน่ะ ลองเช็กดูสิ...",
  ui_story_5014_50141201_19_dialog_content = "<color=#e8d9bb>ขอตรวจสอบ... เครื่องสื่อสาร... ของซีมัส...</color>",
  ui_story_5014_50141201_20_dialog_content = "พี่คะ เอาเครื่องสื่อสารให้บัตเลอร์สิ",
  ui_story_5014_50141201_21_dialog_content = "ได้...",
  ui_story_5014_50141201_22_dialog_content = "<color=#e8d9bb>การตรวจสอบเสร็จสิ้น... ไม่พบ... ประกาศเผยแพร่... ข้อความ...</color>",
  ui_story_5014_50141201_23_dialog_content = "เป็นไปไม่ได้! เราได้รับข้อความนั่นจริง ๆ นะ",
  ui_story_5014_50141201_24_dialog_content = "บัตเลอร์ไม่มีทางโกหกเราอยู่แล้ว แกมันพวกหลอกลวง!",
  ui_story_5014_50141201_25_dialog_content = "ไม่ใช่นะ ฟังฉันก่อน บัตเลอร์น่ะ แค่ตรวจหาสัญญาณนั่นไม่พบ",
  ui_story_5014_50141201_26_dialog_content = "ซีมัสก็แค่อยากจะปิดบังมันจากบัตเลอร์...",
  ui_story_5014_50141201_27_dialog_content = "ฉ-ฉันไม่ได้คิดเรื่องนั้นเลยแฮะ... ขอโทษนะคะ",
  ui_story_5014_50141201_28_dialog_content = "ไม่เป็นไร",
  ui_story_5014_50141201_29_dialog_content = "วาเลนเซีย ฉันยังมีหลักฐานอีกอย่างที่เธอน่าจะ...",
  ui_story_5014_50141201_30_dialog_content = "พี่ อย่าไปฟังนะ พวกเขาจะหลอกพี่อีกแล้ว!",
  ui_story_5014_50141201_31_dialog_content = "อยู่ ๆ ก็โผล่มาในบ้านเรา ทำลายหุ่นพวกนั้น แถมยังทำร้ายบัตเลอร์...",
  ui_story_5014_50141201_32_dialog_content = "เรื่องมันเลยเถิดมาถึงขนาดนี้... พวกนั้นก็ยังกล้าโกหกเราหน้าตาเฉย!",
  ui_story_5014_50141201_33_dialog_content = "*วื้ด*",
  ui_story_5014_50141201_34_dialog_content = "หุ่นพวกนั้นมากันอีกแล้ว",
  ui_story_5014_50141201_35_dialog_content = "ป—ประธาน...!",
  ui_story_5014_50141201_36_dialog_content = "ใจเย็นนะ เอริก้า... อย่าบุ่มบ่ามล่ะ",
  ui_story_5014_50141201_37_dialog_content = "เอาล่ะ ฉันพอจับทางได้ จากที่ผ่านมา ถ้าเราไม่โจมตีก่อน พวกมันก็จะไม่ทำอะไรเรา...",
  ui_story_5014_50141201_38_dialog_content = "ตลกน่า! ฉันมีวิธีอีกมากมายที่จะทำให้พวกเขาโจมตี! เจ้าพวกโกหกหน้าด้าน! ขโมย! ผู้บุกรุก!",
  ui_story_5014_50141201_39_dialog_content = "เกรเทล อย่าใจร้อนนะ...",
  ui_story_5014_50141201_40_dialog_content = "บัตเลอร์ กำจัดพวกมันซะ!",
  ui_story_5014_50141201_41_dialog_content = "ออโรเรียนพวกนี้เป็นศัตรูของเรา! พวกมันเป็นภัยคุกคามต่อเราและเมืองแห่งนี้!",
  ui_story_5014_50141201_42_dialog_content = "<color=#e8d9bb>รับทราบ... คุณเกรเทล...</color>",
  ui_story_5014_50141201_43_dialog_content = "วื้ด!",
  ui_story_5014_50141201_44_dialog_content = "แย่แล้ว... เธอออกคำสั่งจับตาย!",
  ui_story_5014_50141201_45_dialog_content = "เธอสั่งหุ่นยนต์พวกนั้นได้ยังไงน่ะ?!",
  ui_story_5014_50141201_46_dialog_content = "ระวังนะ PlayerName!",
  ui_story_5014_50141201_47_dialog_content = "<color=#e8d9bb>ตูม!</color>",
  ui_story_5014_50141201_48_dialog_content = "จับกุม... จับกุม...",
  ui_story_5014_50141201_49_dialog_content = "<color=#e8d9bb>คำเตือน... เพิ่ม... คำสั่งใหม่...</color>",
  ui_story_5014_50141201_50_dialog_content = "คำสั่งใหม่... ทำลายผู้บุกรุก!",
  ui_story_5014_50141201_51_dialog_content = "ทุกคน! เตรียมตัว...",
  ui_story_5014_50141201_52_dialog_content = "ก๊าาาซ!",
  ui_story_5014_50141201_53_dialog_content = "โห อิคลิพไซท์พวกนั้นมาจากไหนน่ะ?!",
  ui_story_5014_50141201_54_dialog_content = "วาเลนเซีย เกรเทล ระวังข้างหลัง!",
  ui_story_5014_50141201_55_dialog_content = "พูดอะไรของแกน่ะ คิดว่าเจ้าพวกนี้มันตามล่าเรางั้นเรอะ?",
  ui_story_5014_50141201_56_dialog_content = "กรร—กรร!",
  ui_story_5014_50141201_57_dialog_content = "คุณเชอวาน พวกมันเข้ามาใกล้เราเรื่อย ๆ แล้วนะ",
  ui_story_5014_50141201_58_dialog_content = "เหมือนกับว่าอิคลิพไซท์ไม่เห็นวาเลนเซียกับเกรเทลยังงั้นแหละ!",
  ui_story_5014_50141201_59_dialog_content = "เชอวาน ทำไมอิคลิพไซท์ถึงเป็นแบบนี้ล่ะ?",
  ui_story_5014_50141201_60_dialog_content = "แล้วหุ่นยนต์พวกนั้น... มันควรจะต้องสู้กับอิคลิพไซท์ไม่ใช่เหรอ?",
  ui_story_5014_50141201_61_dialog_content = "ขอคิดก่อนนะ...",
  ui_story_5014_50141201_62_dialog_content = "ก่อนหน้านี้ที่อิคลิพไซท์โจมตีเรา หุ่นยนต์พวกนี้ก็สู้กับมัน... แต่ตอนนี้ทั้งสองฝ่ายกลับร่วมมือกัน",
  ui_story_5014_50141201_63_dialog_content = "พวกหุ่นยนต์รับคำสั่งจากพี่น้อง... และปกป้องพวกเธอจากอิคลิพไซท์",
  ui_story_5014_50141201_64_dialog_content = "เกรเทลกับวาเลนเซีย... หรือว่า...",
  ui_story_5014_50141201_65_dialog_content = "อย่าบอกนะว่าเด็กสองคนนั้นควบคุมอิคลิพไซท์ได้?!",
  ui_story_5014_50141202_1_dialog_content = "ไวซ์ จัดการมันเลย!",
  ui_story_5014_50141202_2_dialog_content = "หอกของฉันติดในตัวหุ่น!",
  ui_story_5014_50141202_3_dialog_content = "ให้ฉันจัดการเอง น้ำวนเชี่ยวกราก!",
  ui_story_5014_50141202_4_dialog_content = "*วื้ด*",
  ui_story_5014_50141202_5_dialog_content = "คาร์ลีน อย่าฝืนเลยนะ ระวังอาการบาดเจ็บของเธอด้วย...",
  ui_story_5014_50141202_6_dialog_content = "ไม่ต้องห่วง ฉันไม่ให้อาการบาดเจ็บแค่นี้มาถ่วงหรอก",
  ui_story_5014_50141202_7_dialog_content = "ฉันจัดการหุ่นฝั่งฉันเรียบร้อยแล้ว",
  ui_story_5014_50141202_8_dialog_content = "เอาล่ะ งั้นไปช่วยอาจารย์เชอวานกันเถอะ!",
