  ui_story_5014_50141202_10_dialog_content = "กลับมานะ ไอ้ตัวน่ารังเกียจ!!",
  ui_story_5014_50141202_11_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_5014_50141202_12_dialog_content = "ไม่เอาน่า แผ่นดินไหวอีกแล้วเหรอ!",
