  ui_story_5014_50141301_2_dialog_content = "นี่... นายน่ะ...!",
  ui_story_5014_50141301_3_dialog_content = "PlayerName ใช่ นายนั่นแหละ พวกนั้นยังไล่ตามนายอยู่รึเปล่า?",
