  ui_story_5014_50141301_73_dialog_content = "แต่กว่าจะถึงวันนั้น ฉันก็ไม่รู้เหมือนกันว่านิมบัสกับฉันจะอยู่รอดปลอดภัยรึเปล่า...",
  ui_story_5014_50141301_74_dialog_content = "ถ้าเกิดเรื่องไม่คาดฝันขึ้น... ข้อมูลเหล่านี้... ทั้งหมด... จะเป็นมรดกของฉัน",
  ui_story_5014_50141301_75_dialog_content = "ฉันจะฝากมันไว้ให้กับภรรยา ลูกสาว และสหายร่วมรบ",
  ui_story_5014_50141301_76_dialog_content = "หวังว่าใครก็ตามที่ถอดรหัสข้อความนี้ได้ จะนำมันไปใช้ในทางที่เป็นประโยชน์",
  ui_story_5014_50141301_77_dialog_content = "แล้วซีมัสก็ฝากบันทึกให้วาเลนเซียด้วย",
  ui_story_5014_50141301_78_dialog_content = "อยากให้เรานำไปมอบให้เธอรึเปล่า?",
  ui_story_5014_50141301_79_dialog_content = "เรื่องนั้น เขาอยากจะให้ \"สหายร่วมรบจากอิลลูมินา\" เป็นคนมอบให้แทนตัวเขา",
  ui_story_5014_50141301_80_dialog_content = "แต่ต้องเป็นตอนที่วาเลนเซียพร้อมสำหรับโลกภายนอกแล้วเท่านั้น",
  ui_story_5014_50141301_81_dialog_content = "เขาบอกว่าบันทึกนี้เข้ารหัสไว้ด้วยวิธีที่มีเพียงวาเลนเซียเท่านั้นที่ถอดรหัสได้",
  ui_story_5014_50141301_82_dialog_content = "นอกจากจะฝากข้อมูลให้อิลลูมินาแล้ว เขายังฝากข้อความให้ลูกสาวด้วย...",
  ui_story_5014_50141301_83_dialog_content = "ใช่ ตอนนี้ยังเหลือส่วนสุดท้ายอีก... ฉันกำลังพยายามถอดความอยู่ แต่ทั้งหมดก็มีเท่านี้ล่ะ",
  ui_story_5014_50141301_84_dialog_content = "แต่ถ้าเป็นไดอารี่ของนิมบัสล่ะก็ ทุกอย่างมันเรียบง่ายกว่านั้นเยอะเลย",
  ui_story_5014_50141301_85_dialog_content = "เธอก็ถอดรหัสเสร็จแล้วเหรอ?",
  ui_story_5014_50141301_86_dialog_content = "ใช่ นอกจากข้อมูลบางอย่าง... ที่ฉันไม่ได้รับอนุญาตให้เปิดเผย ก็มีย่อหน้าสุดท้ายนี่ล่ะ ที่ฉันพอจะบอกทุกคนได้",
  ui_story_5014_50141301_87_dialog_content = "มันว่ายังไงรึ?",
  ui_story_5014_50141301_88_dialog_content = "...",
  ui_story_5014_50141301_89_dialog_content = "\"คนที่ถอดรหัสข้อความนี้ได้มีเพียงศาสนจักรแห่งลูโมโพลิสเท่านั้น\"",
  ui_story_5014_50141301_90_dialog_content = "\"โปรดให้บาปของฉันจบลงที่ตัวฉัน ลูกสาวของฉันไม่ได้มีส่วนเกี่ยวข้องใด ๆ ทั้งสิ้น\"",
  ui_story_5014_50141301_91_dialog_content = "\"หากสงครามจบลงแล้ว โปรดช่วยดูแลเด็กน้อยผู้ไร้เดียงสาทั้งสองคนด้วย\"",
  ui_story_5014_50141301_92_dialog_content = "\"แต่ถ้าโลกยังคงถูกคุกคามด้วยปีศาจร้าย ก็ขอจงหันหลังกลับไป โปรดละเว้นดินแดนอันสงบสุขและบริสุทธิ์แห่งนี้ด้วยเถิด\"",
  ui_story_5014_50141301_93_dialog_content = "\"นี่คือคำวิงวอนจากใจจริง... ได้โปรดเถอะ... อย่าทำร้ายลูกสาวของฉันเลย\"",
  ui_story_5014_50141301_94_dialog_content = "\"วาเลนเซีย... เกรเทล... จงก้าวเดินต่อไป ไม่ว่าจะอยู่ในรัตติกาลสีขาวหรือความฝันอันแสนอ่อนโยน\"",
  ui_story_5014_50141301_95_dialog_content = "\"แม่จะอยู่กับลูกเสมอ...\"",
  ui_story_5014_50141301_96_dialog_content = "\"แม่จะจับมือลูก ๆ อยู่เคียงข้างลูก เหมือนอย่างที่เคย...\"",
  ui_story_5014_50141301_97_dialog_content = "\"แม้ในอนาคตอันแสนไกล ทุกอย่างจะยังคงเหมือนเดิม ตลอดไป\"",
  ui_story_5014_50141301_98_dialog_content = "ฉัน... ฉันรู้สึกได้...",
  ui_story_5014_50141301_99_dialog_content = "ฉันมั่นใจว่าแม้แต่เทพแห่งแสงสว่างก็จะต้องซาบซึ้งกับความรักอันไร้เงื่อนไขนี้",
  ui_story_5014_50141301_100_dialog_content = "ซีมัส... นิมบัส... ความรักที่มีให้กับลูก ๆ นั้นช่างลึกซึ้ง",
  ui_story_5014_50141301_101_dialog_content = "เมื่อหลายปีที่แล้ว นิมบัสเดินทางมาที่นี่โดยบังเอิญเนื่องจาก \"ความผิด\" ที่เธอก่อไว้ อีกทั้งยังถูกคุกคามด้วยภัยสงคราม",
  ui_story_5014_50141301_102_dialog_content = "ส่วนซีมัสก็มาที่นี่โดยบังเอิญเพราะภารกิจการสำรวจ และผลกระทบจากสงครามเช่นกัน",
  ui_story_5014_50141301_103_dialog_content = "ระบบ AI และหุ่นยนต์คอยปกป้องพวกเขา",
