  ui_story_5014_50141301_111_dialog_content = "อะแฮ่ม โทษทีที่ขัดจังหวะนะ แต่ในเมื่อตอนนี้เรารู้แล้วว่าเกิดอะไรขึ้น...",
  ui_story_5014_50141301_112_dialog_content = "เราเอาบันทึกและไดอารี่ของทั้งสองคน... กลับไปคืนเด็ก ๆ กันดีมั้ย?",
