  ui_story_5014_50141301_120_dialog_content = "เพราะเขาจะรู้ได้ไงว่าคนแบบไหนจะหล่นลงมาในนี้",
  ui_story_5014_50141301_121_dialog_content = "<color=#e8d9bb>ครืน</color>",
