  ui_story_5014_50141301_132_dialog_content = "เขาเขียนพิกัดทางเข้าด้านล่างไว้ให้ด้วย ก็คงต้องไปตามนั้นแหละ...",
  ui_story_5014_50141301_133_dialog_content = "มาดูกันว่ายังมีระบบที่ยังไม่โดนบัตเลอร์บล็อกเหลืออยู่รึเปล่า",
