  ui_story_5014_50141301_135_dialog_content = "ไม่นะ... หวังว่าเราจะไม่โดนแผ่นดินไหวฝังระหว่างลงไปข้างล่างหรอกนะ...",
  ui_story_5014_50141301_136_dialog_content = "ที่นี่เป็นเมืองใต้ดินอยู่แล้ว เราโดนฝังตั้งแต่เข้ามาแล้วล่ะ",
