  ui_story_5014_50141301_155_dialog_content = "เพื่อเป็นการแลกเปลี่ยน นอกจากพ่อบ้าน AI นั่น... ฉันจะยอมปิดหูปิดตาให้ และจะรายงานเบื้องบนว่าไม่เจออะไรทั้งนั้น",
