  ui_story_5014_50141501_26_dialog_content = "เกรเทล ทุกอย่างที่ฉันพูดเป็นความจริงนะ!",
  ui_story_5014_50141501_27_dialog_content = "บัตเลอร์ อาการพี่เป็นยังไงบ้าง?",
  ui_story_5014_50141501_28_dialog_content = "เกรเทล ฉันไม่เป็นไร... ไม่ต้องห่วง",
  ui_story_5014_50141501_29_dialog_content = "<color=#e8d9bb>เริ่มการตรวจสอบ... ร่างกาย... เหนื่อยล้า... คาดว่า... ถูกกระตุ้นทางจิตใจ...</color>",
  ui_story_5014_50141501_30_dialog_content = "<color=#e8d9bb>การต่อสู้เมื่อครู่... ดุเดือดมาก...</color>",
  ui_story_5014_50141501_31_dialog_content = "แกทำร้ายพี่สาวฉัน!",
  ui_story_5014_50141501_32_dialog_content = "ขอโทษนะ เราไม่มีทางเลือก...",
  ui_story_5014_50141501_33_dialog_content = "วาเลนเซียโจมตีพวกเราก่อน",
  ui_story_5014_50141501_34_dialog_content = "สาเหตุหลักที่เธอเหนื่อยก็เพราะพยายามควบคุมหุ่นยนต์",
  ui_story_5014_50141501_35_dialog_content = "ถ้าไม่เชื่อก็ลองถามบัตเลอร์ดูก็ได้",
  ui_story_5014_50141501_36_dialog_content = "บัตเลอร์ พวกเด็ก ๆ ควบคุมหุ่นยนต์ผ่านนายใช่มั้ย?",
  ui_story_5014_50141501_37_dialog_content = "ทำไมจู่ ๆ นายถึงมีสิทธิ์ออกคำสั่งได้โดยตรง?",
  ui_story_5014_50141501_38_dialog_content = "<color=#e8d9bb>ออโรเรียน... ไม่ได้รับอนุญาตให้เข้าถึงข้อมูล...</color>",
  ui_story_5014_50141501_39_dialog_content = "ฉันไม่จำเป็นต้องถามเขาหรอก บัตเลอร์ไม่ใช่คนโกหก ไม่เหมือนพวกแก",
  ui_story_5014_50141501_40_dialog_content = "<color=#e8d9bb>ข้อมูลของผม... เป็นความจริง...</color>",
  ui_story_5014_50141501_41_dialog_content = "เกรเทล เธอควบคุมระบบของเมืองผ่านบัตเลอร์ใช่มั้ย?",
  ui_story_5014_50141501_42_dialog_content = "ถ้าเธอถามสถานะของแกนพลังงานอีกครั้ง เธอก็จะรู้ว่าที่นี่ไม่ปลอดภัย",
  ui_story_5014_50141501_43_dialog_content = "ไม่ใช่แค่ระบบเท่านั้น ฉันควบคุมทุกอย่างที่นี่ได้...",
  ui_story_5014_50141501_44_dialog_content = "ขอบคุณที่เตือนให้จำได้นะ พวกผู้บุกรุก คนโกหก หัวขโมย!",
  ui_story_5014_50141501_45_dialog_content = "บัตเลอร์ อย่างที่ัฉันบอก เปิดโปรแกรมกับสัญญาณเตือนภัยซะ",
  ui_story_5014_50141501_46_dialog_content = "เกรเทล อย่า...",
  ui_story_5014_50141501_47_dialog_content = "<color=#e8d9bb>รับทราบ กำลังรีเซ็ต... ดำเนินการ... เพิ่มระดับการระวังภัย...</color>",
  ui_story_5014_50141501_48_dialog_content = "ต้องสู้กันอีกแล้วเหรอเนี่ย?",
  ui_story_5014_50141501_49_dialog_content = "อิคลิพไซท์บุกเข้ามาเหมือนก่อนหน้านี้อีกแล้ว... เหมือนมันจงใจเล่นงานพวกเราโดยเฉพาะเลยแฮะ",
  ui_story_5014_50141501_50_dialog_content = "เกรเทลควบคุมพวกมันได้ยังไงกัน...",
  ui_story_5014_50141501_51_dialog_content = "ผมอยากรู้ว่าเราจะตีฝ่าเจ้าพวกน่ารำคาญนี่ไปได้ยังไงมากกว่า",
  ui_story_5014_50141502_1_dialog_content = "ข้างหลังนั่น... ตัวสุดท้ายแล้ว!",
  ui_story_5014_50141502_2_dialog_content = "ยังมีอีกนะ! บุปผาน้ำแข็ง!!",
  ui_story_5014_50141502_3_dialog_content = "ฉันแพ้ได้ยังไง... พวกแกมีกันแค่สามคนแท้ ๆ! ทำไมถึงยังยืนอยู่ได้?!",
  ui_story_5014_50141502_4_dialog_content = "สาม? ไม่ได้นับฉันด้วยรึไง?",
  ui_story_5014_50141502_5_dialog_content = "ฉันคงจะอ่อนแอมากจริง ๆ...",
  ui_story_5014_50141502_6_dialog_content = "เพราะฉันอ่อนแอ พ่อกับแม่ก็เลยต้องตาย...",
  ui_story_5014_50141502_7_dialog_content = "เพราะฉันอ่อนแอ พวกแกก็เลยบุกเข้ามาในบ้านของเราและทำร้ายพี่สาวได้!",
  ui_story_5014_50141502_8_dialog_content = "เกรเทล พวกเขาคงไม่อยากเห็นเธอเป็นแบบนี้หรอกนะ ลองคิดดูสิ...",
  ui_story_5014_50141502_9_dialog_content = "บอกให้ฉันนึกถึงพ่อกับแม่งั้นเหรอ...?",
  ui_story_5014_50141502_10_dialog_content = "ฉันคิดถึงพวกเขาเหลือเกิน... คิดถึงอยู่ตลอดเวลา...",
  ui_story_5014_50141502_11_dialog_content = "แล้วฉันก็คิด ว่าถ้าพวกเขายังอยู่ คงไม่ยอมให้พวกแก...",
  ui_story_5014_50141502_12_dialog_content = "รังแกฉัน... กับพี่...",
  ui_story_5014_50141502_13_dialog_content = "เกรเทล ช่วยใจเย็นแล้วรอให้ฉันอ่านจดหมายของพ่อก่อนได้มั้ย?",
  ui_story_5014_50141502_14_dialog_content = "*สะอื้น*",
  ui_story_5014_50141502_15_dialog_content = "วาเลนเซีย พ่อแม่ของเธอถูกอิคลิพไซท์โจมตีระหว่างที่กำลังหาทางออกใช่มั้ย?",
  ui_story_5014_50141502_16_dialog_content = "ใช่ แต่เกรเทล... เธอจำเรื่องนี้ไม่ได้... ฉันจะพูดเรื่องนี้ต่อหน้าเธอไม่ได้",
  ui_story_5014_50141502_17_dialog_content = "ที่รัก มีแผ่นดินไหวอีกแล้ว",
  ui_story_5014_50141502_18_dialog_content = "นั่นสินะ... เป็นสัญญาณไม่ดีเลย",
  ui_story_5014_50141502_19_dialog_content = "รอให้มันหยุดก่อนดีมั้ย แล้วเราค่อยหาทางออกกันต่อ",
  ui_story_5014_50141502_20_dialog_content = "ฉันก็คิดแบบนั้นเหมือนกัน อย่างน้อยในเมืองก็พอจะปกป้องเราได้บ้าง",
  ui_story_5014_50141502_21_dialog_content = "รีบกลับกันเถอะ...",
  ui_story_5014_50141502_22_dialog_content = "ก๊าาาซ!",
  ui_story_5014_50141502_23_dialog_content = "อิคลิพไซท์?! ที่นี่เนี่ยนะ?!",
  ui_story_5014_50141502_24_dialog_content = "ให้ตายสิ! พวกหุ่นยนต์คุ้มกันหยุดทำงานเพราะแผ่นดินไหว...",
  ui_story_5014_50141502_25_dialog_content = "หนีกันเถอะ! ทางนี้!",
  ui_story_5014_50141502_26_dialog_content = "ปวดหัว... ฉันไม่อยากนึกถึงเรื่องนี้... ไม่นะ... ฮึก",
  ui_story_5014_50141502_27_dialog_content = "เกรเทล เป็นอะไรไป?! พี่อยู่นี่แล้ว ไม่ต้องกลัวนะ...",
  ui_story_5014_50141502_28_dialog_content = "<color=#e8d9bb>ปัง!</color>",
  ui_story_5014_50141502_29_dialog_content = "แม่ เข้ามาเร็ว!",
  ui_story_5014_50141502_30_dialog_content = "<color=#e8d9bb>คลิก—คลิก—คลิก...</color>",
  ui_story_5014_50141502_31_dialog_content = "ทำไม—ทำไมถึงเปิดไม่ออกล่ะ? แม่คะ หนูเปิดประตูไม่ได้!",
  ui_story_5014_50141502_32_dialog_content = "ประตูไม่ขยับเลย!!",
  ui_story_5014_50141502_33_dialog_content = "แม่เป็นคนล็อกประตูเองแหละ... ลูกอยู่ในนั้นอย่าออกมานะ",
  ui_story_5014_50141502_34_dialog_content = "รีบหาที่ซ่อนเถอะ... พ่อกับแม่ไม่เป็นไรหรอก",
  ui_story_5014_50141502_35_dialog_content = "วาเลนเซีย เกรเทล... ลูก ห้ามออกมาเด็ดขาดนะ... แค่ก",
  ui_story_5014_50141502_36_dialog_content = "แม่?",
  ui_story_5014_50141502_37_dialog_content = "เกิดอะไรขึ้นน่ะ แม่?!",
  ui_story_5014_50141502_38_dialog_content = "*สะอื้น* เปิดประตูสิคะ ได้โปรด...",
  ui_story_5014_50141502_39_dialog_content = "ปกป้อง... น้องสาวของลูก... ด้วยนะ",
  ui_story_5014_50141502_40_dialog_content = "...",
  ui_story_5014_50141502_41_dialog_content = "อ๊าาาากกกกกก!!",
  ui_story_5014_50141502_42_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_5014_50141502_43_dialog_content = "เธอระเบิดพลังออกมาอีกแล้วงั้นเหรอ?!",
  ui_story_5014_50141502_44_dialog_content = "<color=#e8d9bb>คำเตือน! คำเตือน!</color>",
  ui_story_5014_50141502_45_dialog_content = "<color=#e8d9bb>มีการเข้าถึงโดยไม่ได้รับอนุญาต... ผู้บุกรุก! กำลังเข้าไปใน... พื้นที่แกนกลาง!</color>",
  ui_story_5014_50141502_46_dialog_content = "ฟลอรีนกับคนอื่น ๆ งั้นเหรอ?",
  ui_story_5014_50141502_47_dialog_content = "บัตเลอร์บอกว่า... จะต้องปกป้องแกนกลาง...",
  ui_story_5014_50141502_48_dialog_content = "<color=#e8d9bb>ผู้บุกรุก... จะ... ทำลาย... ทุกอย่าง...</color>",
  ui_story_5014_50141502_49_dialog_content = "<color=#e8d9bb>ทำลาย... ทุกอย่าง...!</color>",
  ui_story_5014_50141502_50_dialog_content = "อย่าไปฟังคำพูดของมันนะ!",
  ui_story_5014_50141502_51_dialog_content = "ที่นี่จะถล่มแล้ว และเพื่อนเราก็พยายามหาทางออกอยู่!",
  ui_story_5014_50141502_52_dialog_content = "ต้องช่วยบัตเลอร์... กำจัดพวกแก!",
  ui_story_5014_50141502_53_dialog_content = "*วื้ด*",
  ui_story_5014_50141601_1_dialog_content = "บุก!",
  ui_story_5014_50141601_2_dialog_content = "*วื้ด*",
  ui_story_5014_50141601_3_dialog_content = "ฉันบอกให้บุก!!",
  ui_story_5014_50141601_4_dialog_content = "*วื้ด*",
  ui_story_5014_50141601_5_dialog_content = "ไปสิ บัตเลอร์! มัวทำอะไรอยู่?!",
  ui_story_5014_50141601_6_dialog_content = "<color=#e8d9bb>โปรแกรมกวาดล้าง... โปรแกรมกวาดล้าง... โปรแกรมกวาดล้าง...</color>",
  ui_story_5014_50141601_7_dialog_content = "อิคลิพไซท์ตรงโน้นก็มีอยู่เยอะแยะไม่ใช่หรือไง?! สั่งพวกมันสิ!",
  ui_story_5014_50141601_8_dialog_content = "<color=#e8d9bb>ดำเนินคำสั่ง... ฆ่าทุกอย่าง... ไม่มีข้อยกเว้น!</color>",
  ui_story_5014_50141601_9_dialog_content = "กรร...",
  ui_story_5014_50141601_10_dialog_content = "ก๊าาาาซ!!",
  ui_story_5014_50141601_11_dialog_content = "บัตเลอร์สั่งการพวกอิคลิพไซท์งั้นเหรอ?",
  ui_story_5014_50141601_12_dialog_content = "ที่เกรเทลควบคุมหุ่นยนต์ได้ก็เพราะบัตเลอร์ที่เป็นคนสร้างหุ่นน่ะ ฟังคำสั่งเธอ",
  ui_story_5014_50141601_13_dialog_content = "แต่คราวนี้บัตเลอร์สั่งอิคลิพไซท์ได้ มันก็หมายความว่า...",
  ui_story_5014_50141601_14_dialog_content = "บัตเลอร์มีความสามารถในการสร้างอิคลิพไซท์งั้นเหรอ?",
  ui_story_5014_50141601_15_dialog_content = "มันเคยปฏิเสธเรื่องนี้ไปแล้วนี่",
  ui_story_5014_50141601_16_dialog_content = "ถ้างั้นแสดงว่าหุ่นพวกนี้โกหกเป็น... ที่บอกว่า \"บัตเลอร์พูดแต่ความจริง\" ก็โกหกเด็กพวกนั้น",
  ui_story_5014_50141601_17_dialog_content = "ตอนนี้เราต้องจัดการศัตรูพวกนี้ให้ได้ก่อน",
  ui_story_5014_50141601_18_dialog_content = "แต่พวกมันมากันไม่หยุดเลย...",
  ui_story_5014_50141601_19_dialog_content = "ดูเหมือนเราต้องหยุดคนที่ออกคำสั่งให้ได้ก่อน...",
  ui_story_5014_50141601_X19_dialog_content = "เกรเทล",
  ui_story_5014_50141601_20_dialog_content = "<color=#e8d9bb>คำเตือน... ตรวจพบ... อันตรายระดับสูงสุด... หนีไป... เกรเทล...</color>",
  ui_story_5014_50141601_21_dialog_content = "เดี๋ยว หยุดนะ! อย่าทำร้ายเกรเทล!",
  ui_story_5014_50141601_22_dialog_content = "เธอไม่รู้ตัวว่ากำลังทำอะไรอยู่!",
  ui_story_5014_50141601_23_dialog_content = "โจมตี... โจมตี... ทุกคน—ทุกคน...",
  ui_story_5014_50141601_24_dialog_content = "กำจัดพวกมันให้หมด...!",
  ui_story_5014_50141601_25_dialog_content = "<color=#e8d9bb>คำเตือน... เป้าหมายสำคัญ... ตกอยู่ในอันตราย!</color>",
  ui_story_5014_50141601_26_dialog_content = "แย่แล้ว บัตเลอร์คิดว่าเราพยายามจะทำร้ายเกรเทล",
  ui_story_5014_50141601_27_dialog_content = "<color=#e8d9bb>ปัง! ปัง!</color>",
  ui_story_5014_50141601_28_dialog_content = "ไปให้พ้น! ฉันจะไม่ให้แกทำอะไรเกรเทลเด็ดขาด!",
  ui_story_5014_50141601_29_dialog_content = "พวกแกทุกคน! ถอยไป!",
  ui_story_5014_50141601_30_dialog_content = "ฉัน... ต้อง... ปกป้อง... บ้าน...",
  ui_story_5014_50141601_31_dialog_content = "พี่...",
  ui_story_5014_50141601_32_dialog_content = "เกรเทล ตั้งสติดี ๆ นะ แล้วฟังพี่... ควบคุมอารมณ์ให้ได้!",
  ui_story_5014_50141601_33_dialog_content = "วาเลนเซีย ให้เราช่วยอีกแรงนะ! ฉันอาจจะช่วยเธอได้!",
  ui_story_5014_50141601_34_dialog_content = "ถอยไป!",
  ui_story_5014_50141601_35_dialog_content = "อย่าเข้ามาใกล้น้องสาวของฉัน!",
  ui_story_5014_50141602_1_dialog_content = "พี่... พี่...",
  ui_story_5014_50141602_2_dialog_content = "เกรเทล... ดีจัง... ในที่สุดเธอก็สงบลงแล้ว!",
  ui_story_5014_50141602_3_dialog_content = "อยู่นิ่ง ๆ นะ พักให้สบาย...",
  ui_story_5014_50141602_4_dialog_content = "บัตเลอร์ ตรวจร่างกายน้องของฉันที!",
  ui_story_5014_50141602_5_dialog_content = "<color=#e8d9bb>รับทราบ... กำลังเริ่มต้น... การตรวจสอบ...</color>",
  ui_story_5014_50141602_6_dialog_content = "ขอโทษนะ ทางเราก็ต้องป้องกันตัวเอง...",
  ui_story_5014_50141602_7_dialog_content = "เธอไม่บาดเจ็บอะไรใช่มั้ย?",
  ui_story_5014_50141602_8_dialog_content = "ฉันไม่เป็นไร... แต่น้องสาวฉันเกลียดพวกคุณ อย่าเพิ่งเข้าไปใกล้เธอเลยนะ...",
  ui_story_5014_50141602_9_dialog_content = "อารมณ์ของเธออ่อนไหว... อาจจะโมโหขึ้นมาอีกก็ได้",
  ui_story_5014_50141602_10_dialog_content = "เข้าใจแล้ว ในเมื่อตอนนี้เธอสงบลงแล้ว เราก็จะไม่ยุ่งกับเธอ",
  ui_story_5014_50141602_11_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_5014_50141602_12_dialog_content = "วาเลนเซีย มีแผ่นดินไหวอีกแล้วนะ ทุกอย่างดูท่าทางไม่ดีเลย...",
  ui_story_5014_50141602_13_dialog_content = "ฉันอยากอ่านจดหมายของพ่อ... ขอเวลาอีกเดี๋ยวได้มั้ย",
  ui_story_5014_50141602_14_dialog_content = "ได้สิ... ไม่เป็นไรนะ ตามสบายเลย...",
  ui_story_5014_50141602_15_dialog_content = "พวกคุณรอตรงนี้แหละ อย่าเข้าใกล้พวกเรา แล้วก็อย่าไปไหนด้วย...",
  ui_story_5014_50141602_16_dialog_content = "บัตเลอร์ เอาหุ่นมาเฝ้าพวกเขาที... ไปหาที่ที่ปลอดภัยกันเถอะ",
  ui_story_5014_50141602_17_dialog_content = "<color=#e8d9bb>รับทราบ</color>",
  ui_story_5014_50141602_18_dialog_content = "วาเลนเซีย",
  ui_story_5014_50141602_19_dialog_content = "ถ้าลูกได้อ่านจดหมายฉบับนี้ ก็แสดงว่าพ่อคงจะไม่ได้อยู่กับลูกอีกแล้ว",
  ui_story_5014_50141602_20_dialog_content = "พ่อไม่รู้เหมือนกันว่าตัวเองจะจากไปเพราะอะไร แต่แน่นอนว่าไม่ใช่เพราะพ่ออยากจะทิ้งลูก",
  ui_story_5014_50141602_21_dialog_content = "พ่อไม่มีทางทิ้งพวกหนูไปไหน",
  ui_story_5014_50141602_22_dialog_content = "แต่ความเป็นไปของโลกและชะตากรรมนั้น ไม่ใช่สิ่งที่เราควบคุมได้",
  ui_story_5014_50141602_23_dialog_content = "แม่ของลูก และตัวพ่อเอง... เราเผชิญกับอุปสรรคมามากมาย และมีหลายครั้งหลายหนที่อยากจะยอมแพ้",
  ui_story_5014_50141602_24_dialog_content = "แต่ทุกสิ่งเปลี่ยนไปเมื่อพวกเรามีลูกเข้ามาในชีวิต",
  ui_story_5014_50141602_25_dialog_content = "ทุกครั้งที่พ่อเห็นรอยยิ้มของหนู ศรัทธาของพ่อก็กลับฟื้นคืนอีกครั้ง...",
  ui_story_5014_50141602_26_dialog_content = "พ่อจะต้องสร้างชีวิตที่ดีกว่าให้ลูก",
  ui_story_5014_50141602_27_dialog_content = "ในตอนที่อ่านจดหมายฉบับนี้ ลูกอาจจะได้ออกจาก \"บ้าน\" แล้ว และก้าวไปบนดินแดนที่แท้จริงอันกว้างใหญ่ไพศาล",
  ui_story_5014_50141602_28_dialog_content = "หรือไม่ก็อาจจะกำลังยืนหยัดอย่างเข้มแข็ง... ปกป้องน้องกับแม่",
  ui_story_5014_50141602_29_dialog_content = "ไม่ว่ามันจะออกมาเป็นอย่างไร ลูกทำได้ดีมาก วาเลนเซีย และพ่อก็ภูมิใจในตัวลูกเสมอ",
  ui_story_5014_50141602_30_dialog_content = "ถ้าลูกออกไปจากที่นี่ได้ พ่อก็จะสบายใจและหมดห่วง",
  ui_story_5014_50141602_31_dialog_content = "ลูกจะได้เห็นภูเขา แม่น้ำ ทะเลสาบและมหาสมุทร.... เหยียบย่างบนทุ่งหญ้าที่ผันเปลี่ยนไปทุกฤดูกาล ได้เห็นดวงอาทิตย์ขึ้นพ้นขอบฟ้าและลาลับไปในยามค่ำ",
  ui_story_5014_50141602_32_dialog_content = "ลูกจะได้จับมือกับน้องสาวและแม่ สร้างบ้านหลังใหม่ ตัดเย็บเสื้อผ้าสวย ๆ และได้กลิ่นอาหารแสนอร่อย",
  ui_story_5014_50141602_33_dialog_content = "ลูกจะชอบที่ได้แหงนหน้ามองท้องฟ้าจริง ๆ ทั้งกลางวันและกลางคืน",
  ui_story_5014_50141602_34_dialog_content = "แต่ก็ต้องเผชิญหน้ากับความมืดมิด",
  ui_story_5014_50141602_35_dialog_content = "ความหนาวเย็นอันกัดกิน ลมกระโชกโหยหวน และศัตรูที่น่ากลัวยิ่งกว่าที่ลูกเคยจินตนาการ",
  ui_story_5014_50141602_36_dialog_content = "แต่พวกมันไม่มีทางทำอะไรลูกได้หรอก วาเลนเซีย",
  ui_story_5014_50141602_37_dialog_content = "เพราะเมื่อถึงเวลาที่ลูกได้อ่านจดหมายฉบับนี้ ก็แสดงว่าลูกได้เติบโตเป็นผู้ใหญ่แล้ว",
  ui_story_5014_50141602_38_dialog_content = "พ่อมั่นใจว่าเพื่อนร่วมชาติชาวอิลลูมินาจะหาลูกพบ และรับลูกเข้าเป็นส่วนหนึ่งของพวกเขา",
  ui_story_5014_50141602_39_dialog_content = "ลูกจะได้รู้ว่าที่จริงแล้วครอบครัวของเราใหญ่แค่ไหน",
  ui_story_5014_50141602_40_dialog_content = "หลังจากที่ลูกได้ผ่านความยากลำบากมามากมายนับไม่ถ้วนเหมือนพ่อกับแม่...",
  ui_story_5014_50141602_41_dialog_content = "ลูกอาจจะได้เจอกับบ้านหลังใหม่ และคนที่พร้อมดูแลลูกเสมอ",
  ui_story_5014_50141602_42_dialog_content = "อืมม... พูดอย่างนี้แล้ว ก็อดไม่ได้ที่จะอิจฉานิดหน่อยนะ...",
  ui_story_5014_50141602_43_dialog_content = "คนที่จะคอยดูแลลูกตลอดเวลาน่ะเหรอ? เขาจะเป็นใครกันนะ พ่อเองก็อยากเห็นเหมือนกัน",
  ui_story_5014_50141602_44_dialog_content = "พ่อยินดีเสียสละทุกอย่างเพื่อให้อนาคตอันสดใสเหล่านั้นเป็นความจริง",
  ui_story_5014_50141602_45_dialog_content = "น่าเสียดายที่ตอนนี้ชีวิตของเรายังอยู่ในกำมือของคนอื่น...",
  ui_story_5014_50141602_46_dialog_content = "ไม่สิ มันเป็นสิ่งที่สลับซับซ้อนยิ่งกว่านั้น... นั่นก็คือ AI โบราณ",
  ui_story_5014_50141602_47_dialog_content = "ถ้าเกิดโชคร้าย... ที่อนาคตเหล่านั้นยังไม่เป็นจริง ลูกจะต้องจำคำที่พ่อบอกต่อไปนี้ให้ดี",
  ui_story_5014_50141602_48_dialog_content = "เมืองแห่งนี้ถึงจุดจบแล้ว และแม้แต่บัตเลอร์ก็ไม่อาจหยุดยั้งมันได้",
  ui_story_5014_50141602_49_dialog_content = "เมื่อสิ่งต่าง ๆ เริ่มพังทลาย พ่ออยากให้ลูกจับมือกับผู้คนที่อยู่รอบตัว และเผชิญหน้าไปด้วยกัน",
  ui_story_5014_50141602_50_dialog_content = "เพราะเมื่อถึงเวลานั้น ที่นี่ก็จะไม่ใช่บ้านของลูกอีกต่อไป บ้านของลูกคือที่ที่มีลูกและผู้คนเหล่านั้นอยู่...",
  ui_story_5014_50141602_51_dialog_content = "\"...นั่นล่ะคือบ้านที่แท้จริง\"",
  ui_story_5014_50141602_52_dialog_content = "พ่อคะ...",
  ui_story_5014_50141602_53_dialog_content = "เกรเทล ฉันจะเชื่อพวกเขาอีกสักครั้ง...",
  ui_story_5014_50141602_54_dialog_content = "เกรเทล? บัตเลอร์? พวกเธออยู่ไหน?",
  ui_story_5014_50141602_55_dialog_content = "คุณเชอวาน...",
  ui_story_5014_50141602_56_dialog_content = "ยอดเลย เธอออกมาแล้ว",
  ui_story_5014_50141602_57_dialog_content = "ฉันสัมผัสได้ว่าเกรเทลไปจากที่นี่แล้ว ก็เลยนึกว่าพวกเธอ...",
