  ui_story_5014_50141602_59_dialog_content = "<color=#e8d9bb>ครืน</color>",
  ui_story_5014_50141602_60_dialog_content = "<color=#e8d9bb>*คึ่ก—คึ่ก*</color>",
  ui_story_5014_50141602_61_dialog_content = "ดูนั่นสิ ท้องฟ้า...",
