  ui_story_5014_50141602_65_dialog_content = "อีกไม่นานทุกอย่างก็จะถล่มลงมา เหมือนตึกรามบ้านช่องทั้งหลาย...",
  ui_story_5014_50141602_66_dialog_content = "พังทลายเหลือแต่ซาก... ถูกกลบฝังไปตลอดกาล",
  ui_story_5014_50141602_67_dialog_content = "แต่พ่อของเธอไม่อยากให้เธอกับเกรเทลต้องหายไปกับสิ่งเหล่านี้...",
  ui_story_5014_50141602_68_dialog_content = "เขาก็เลยหาทางออกอยู่ตลอดเวลา พยายามซ่อมแกนกลาง และส่งข้อความถึงโลกภายนอกอย่างต่อเนื่อง...",
  ui_story_5014_50141602_69_dialog_content = "แต่บัตเลอร์ก็คอยขัดขวางเขา",
  ui_story_5014_50141602_70_dialog_content = "เพื่อหลบสายตาบัตเลอร์ เขาไม่สามารถทำเรื่องพวกนี้ได้อย่างเปิดเผย",
  ui_story_5014_50141602_71_dialog_content = "บอกเธอตรง ๆ ก็ไม่ได้ด้วยซ้ำ",
  ui_story_5014_50141602_72_dialog_content = "วาเลนเซีย พาเกรเทลมาเถอะ พวกเราจะออกไปด้วยกัน",
