  ui_story_5014_50141602_75_dialog_content = "บัตเลอร์อาจจะโกหกเธอ แต่ตอนนี้เกรเทลต้องการเธอนะ... วาเลนเซีย",
  ui_story_5014_50141602_76_dialog_content = "วาเลนเซีย เธอเป็นพี่สาว และฉันรู้ว่าการดูแลน้องด้วยตัวคนเดียวตลอดหลายปีที่ผ่านมามันเหนื่อยแค่ไหน",
  ui_story_5014_50141602_77_dialog_content = "แต่เธอจะต้องทำหน้าที่นี้... ไปบอกเกรเทลซะ ว่าอะไรคือสิ่งที่ถูกต้อง",
  ui_story_5014_50141602_78_dialog_content = "ใช่แล้ว เธอคือคนที่จะต้องทำหน้าที่ชี้แนะน้องสาว ไม่ใช่บัตเลอร์",
  ui_story_5014_50141602_79_dialog_content = "ฉัน...",
  ui_story_5014_50141602_80_dialog_content = "ฉันรู้ว่าเธอพยายามเต็มที่แล้ว...",
  ui_story_5014_50141602_81_dialog_content = "การเลี้ยงดูคนไม่ใช่งานง่าย ๆ เลย ยิ่งไม่มีประสบการณ์อย่างเธอด้วย",
  ui_story_5014_50141602_82_dialog_content = "แต่ตอนนี้ เธอจะต้องโน้มน้าวน้องสาวให้ได้",
  ui_story_5014_50141602_83_dialog_content = "อย่าให้มืดบอดไปกับสถานการณ์ตรงหน้า ปิดตัวเองจากทุกคน",
  ui_story_5014_50141602_84_dialog_content = "เธอเห็นด้วยกับสิ่งที่ฉันพูดมาจนถึงตอนนี้รึเปล่า?",
  ui_story_5014_50141602_85_dialog_content = "ค—ค่ะ... คิดว่านะ",
  ui_story_5014_50141602_86_dialog_content = "เราต้องหาเกรเทลให้เจอโดยด่วน ฉันเป็นห่วงเธอมากเลย",
  ui_story_5014_50141602_87_dialog_content = "อืมม... ฉันพอจะคิดอะไรออก...",
  ui_story_5014_50141602_88_dialog_content = "พ่อเคยให้เซ็นเซอร์เอาไว้... ฉันใช้มันหาตำแหน่งของเธอได้",
  ui_story_5014_50141701_1_dialog_content = "แต่เพราะแผ่นดินไหวเฮงซวยนี่ สัญญาณเซ็นเซอร์ก็เลยผิดปกติ",
