  ui_story_5014_50141701_3_dialog_content = "เป็นไงบ้าง? ให้ฉันช่วยมั้ย?",
  ui_story_5014_50141701_4_dialog_content = "ไม่เป็นไรค่ะ... ฉันจัดการได้ ขอเวลาอีกเดี๋ยว",
  ui_story_5014_50141701_5_dialog_content = "ฉันจะไปลองหาสัญญาณตรงโน้น รอตรงนี้นะ",
  ui_story_5014_50141701_6_dialog_content = "เราจะไปกับเธอ...",
  ui_story_5014_50141701_7_dialog_content = "กลัวว่าฉันจะหนีหรือไง? ฉันไม่หนีหรอกน่า",
  ui_story_5014_50141701_8_dialog_content = "แต่...",
  ui_story_5014_50141701_9_dialog_content = "คาร์ลีน ให้เธอไปเถอะ",
  ui_story_5014_50141701_10_dialog_content = "ไปสิ วาเลนเซีย เราจะรออยู่ตรงนี้",
  ui_story_5014_50141701_11_dialog_content = "ได้เลย",
  ui_story_5014_50141701_12_dialog_content = "คุณเชอวาน จะดีเหรอที่ให้เธอไปคนเดียวแบบนั้น?",
  ui_story_5014_50141701_13_dialog_content = "คนเราจำเป็นต้องหาสัญญาณตัวคนเดียวด้วยเหรอ?",
  ui_story_5014_50141701_14_dialog_content = "ความเชื่อใจก็ต้องซื้อด้วยใจ... เธออาจจะอยากอยู่ตามลำพังสักพัก",
  ui_story_5014_50141701_15_dialog_content = "หรือไม่ก็แค่จะทดสอบพวกเรา",
  ui_story_5014_50141701_16_dialog_content = "ความคิดของเด็กน่ะเรียบง่ายตรงไปตรงมา และฉันก็ไม่อยากจะสงสัยเธอ",
  ui_story_5014_50141701_17_dialog_content = "นอกจากนี้... เรายังมีเคเลสไทต์ที่เป็นเหมือนเซ็นเซอร์มนุษย์อยู่แล้ว",
  ui_story_5014_50141701_18_dialog_content = "แบบว่า ถ้าเธอไม่ไปไหนไกล ผมก็ยังสัมผัสรับรู้ได้",
  ui_story_5014_50141701_19_dialog_content = "เธออยู่ใกล้ ๆ นี่แหละ...",
  ui_story_5014_50141701_20_dialog_content = "อืมม... แล้วถ้าวาเลนเซียรู้เรื่องนี้ล่ะ? เธอจะคิดว่าเราหลอกลวงเธออีกรึเปล่า?",
  ui_story_5014_50141701_21_dialog_content = "กว่าจะให้เธอเชื่อใจมันช่างยากเย็น แล้วฉันก็ไม่อยาก...",
  ui_story_5014_50141701_22_dialog_content = "อะแฮ่ม ไม่ต้องพูดถึงเรื่องนี้เลยก็แล้วกัน...",
  ui_story_5014_50141701_23_dialog_content = "เฮ้อ กว่าจะโน้มน้าวเธอได้ มันยากสุด ๆ เลย สาเหตุสำคัญก็เพราะซีมัสเลือกที่จะสื่อสารด้วยวิธีนี้",
  ui_story_5014_50141701_24_dialog_content = "คุณเชอวาน เมื่อกี้คุณบอกว่าซีมัสพยายามจะ \"ไม่ให้บัตเลอร์จับได้\" เหรอคะ?",
  ui_story_5014_50141701_25_dialog_content = "ใช่ เขาก็เลยแบ่งข้อความออกเป็นหลายส่วนและเข้ารหัสเพื่อให้ข้อมูลปลอดภัย",
  ui_story_5014_50141701_26_dialog_content = "แม้ว่าบัตเลอร์จะได้ข้อมูลไปหรือทำลายไปบางส่วน ก็จะยังมีส่วนอื่นเหลือรอดอยู่มากพอที่จะปะติดปะต่อเรื่องราว",
