  ui_story_5014_50141701_28_dialog_content = "แม้แต่นิมบัสก็ใช้ชวเลขในการเขียนข้อความ",
  ui_story_5014_50141701_29_dialog_content = "ทุกอย่างก็เพื่อป้องกันไม่ให้บัตเลอร์แอบอ่าน",
  ui_story_5014_50141701_30_dialog_content = "ใช่แล้ว",
  ui_story_5014_50141701_31_dialog_content = "ที่จริงแล้วมันก็มีเหตุผลในอีกมุมนึงเหมือนกัน",
  ui_story_5014_50141701_32_dialog_content = "ในฐานะพ่อแม่ของเด็กพวกนั้น... เราไม่มีทางรู้เลยว่าลูกของเราจะพร้อมสำหรับเรื่องนี้รึเปล่า",
