  ui_story_5014_50141701_34_dialog_content = "ถึงซีมัสกับนิมบัสจะพยายามสอนอย่างเต็มที่ให้ลูกแยกแยะคนดีกับคนชั่ว...",
  ui_story_5014_50141701_35_dialog_content = "แต่มันก็ยังมีโอกาสที่ลูกจะมองคนผิดอยู่ดี",
