  ui_story_5014_50141701_37_dialog_content = "มีเพียงการตั้งคำถามและรวบรวมข้อมูลจากหลายแง่มุมเท่านั้น ที่จะทำให้เด็ก ๆ มีสติและเตรียมพร้อมอยู่เสมอ",
