  ui_story_5014_50141701_39_dialog_content = "เครื่องจักรเองก็โกหกเป็นเหมือนกัน แต่เกรเทลไม่เคยสงสัยเลย",
  ui_story_5014_50141701_40_dialog_content = "เกรเทลยังเด็กเกินไปตอนที่พ่อแม่ของเธอจากไป...",
