  ui_story_5014_50141701_42_dialog_content = "อะแฮ่ม แค่ก แค่ก...",
  ui_story_5014_50141701_43_dialog_content = "ขอโทษนะ ไม่รู้ว่าทำไมสำลักออกมา... ว่าแต่ทำไมจู่ ๆ ถึงถามแบบนี้ล่ะ?",
  ui_story_5014_50141701_44_dialog_content = "โทษที... ฉันแค่คิดว่าแนวคิดของอาจารย์เชอวานมันใช่มาก ๆ เลย",
